      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Voice-Leading Cost Explorer</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:30px;min-height:100vh}h1{font-size:1.5em;margin-bottom:5px;color:#ffd93d}h2{font-size:.85em;color:#888;margin-bottom:25px;font-weight:normal}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:800px;width:100%}.card{background:#1a1a3a;border-radius:12px;padding:20px;border:1px solid #333}.card h3{color:#6bcb77;margin-bottom:12px;font-size:1em}.card.wide{grid-column:1/3}.row{display:flex;gap:15px;align-items:center;margin:8px 0;flex-wrap:wrap}.row label{color:#aaa;min-width:30px;font-size:.9em}input[type=range]{flex:1;min-width:80px;accent-color:#ffd93d}input[type=range]::-webkit-slider-thumb{cursor:pointer}.val{background:#222;padding:3px 10px;border-radius:6px;font-family:monospace;min-width:35px;text-align:center;font-size:.95em}.result{font-size:1.3em;font-weight:bold;color:#ffd93d;text-align:center;margin:10px 0}.eq{color:#888;font-size:1em;text-align:center;margin:5px 0;font-family:monospace}.check{font-size:1.1em;text-align:center;margin:8px 0}.bar-container{display:flex;align-items:center;gap:8px;margin:4px 0}.bar{height:20px;border-radius:4px;transition:width .2s}.bar-label{font-size:.8em;color:#aaa;min-width:60px}</style></head><body><h1>Voice-Leading Cost Explorer</h1><h2>Adjust voice motions to see the L¹ seminorm, lattice operations, and the meet-join identity</h2><div class='grid'><div class='card'><h3>Voice Motion m₁</h3><div class='row'><label>Bass</label><input type='range' min='-6' max='6' value='3' id='m1b'><span class='val' id='m1bv'>3</span></div><div class='row'><label>Sop.</label><input type='range' min='-6' max='6' value='-1' id='m1s'><span class='val' id='m1sv'>-1</span></div><div class='result'>cost(m₁) = <span id='c1'>4</span></div><div class='bar-container'><span class='bar-label'>|bass|</span><div class='bar' id='b1b' style='width:50px;background:#ff6b6b'></div></div><div class='bar-container'><span class='bar-label'>|sop.|</span><div class='bar' id='b1s' style='width:17px;background:#ff8a8a'></div></div></div><div class='card'><h3>Voice Motion m₂</h3><div class='row'><label>Bass</label><input type='range' min='-6' max='6' value='1' id='m2b'><span class='val' id='m2bv'>1</span></div><div class='row'><label>Sop.</label><input type='range' min='-6' max='6' value='4' id='m2s'><span class='val' id='m2sv'>4</span></div><div class='result'>cost(m₂) = <span id='c2'>5</span></div><div class='bar-container'><span class='bar-label'>|bass|</span><div class='bar' id='b2b' style='width:17px;background:#6bcb77'></div></div><div class='bar-container'><span class='bar-label'>|sop.|</span><div class='bar' id='b2s' style='width:67px;background:#8aeba0'></div></div></div><div class='card'><h3>Triangle Inequality</h3><div class='eq'>cost(m₁ + m₂) ≤ cost(m₁) + cost(m₂)</div><div class='result'><span id='csum'>?</span> ≤ <span id='csumbound'>?</span></div><div class='check' id='tri-check'>✓ Holds</div></div><div class='card'><h3>Retrograde Symmetry</h3><div class='eq'>cost(−m₁) = cost(m₁)</div><div class='result'><span id='cneg'>?</span> = <span id='cpos'>?</span></div><div class='check' id='neg-check'>✓ Holds</div></div><div class='card wide'><h3>L¹-Lattice Identity: cost(m₁ ∧ m₂) + cost(m₁ ∨ m₂) = cost(m₁) + cost(m₂)</h3><div style='display:flex;gap:30px;justify-content:center;flex-wrap:wrap'><div><div class='eq'>m₁ ∧ m₂ = (<span id='meetv'>?</span>)</div><div class='result' style='font-size:1em'>cost = <span id='cmeet'>?</span></div></div><div><div class='eq'>m₁ ∨ m₂ = (<span id='joinv'>?</span>)</div><div class='result' style='font-size:1em'>cost = <span id='cjoin'>?</span></div></div></div><div class='result' style='margin-top:15px'><span id='lhs'>?</span> = <span id='rhs'>?</span></div><div class='check' id='lattice-check'>✓ Identity holds!</div></div><div class='card wide'><h3>Absolute Homogeneity: cost(c · m₁) = |c| · cost(m₁)</h3><div class='row'><label>c</label><input type='range' min='-5' max='5' value='2' id='scalar'><span class='val' id='scalarv'>2</span></div><div class='result'>cost(<span id='sv'>2</span> · m₁) = <span id='chom_l'>?</span> &nbsp;&nbsp; | &nbsp;&nbsp; |<span id='sv2'>2</span>| · cost(m₁) = <span id='chom_r'>?</span></div><div class='check' id='hom-check'>✓ Holds</div></div></div><script>const ids='m1b m1s m2b m2s scalar'.split(' ');function $(id){return document.getElementById(id)}function cost(a,b){return Math.abs(a)+Math.abs(b)}function update(){const m1b=+$('m1b').value,m1s=+$('m1s').value,m2b=+$('m2b').value,m2s=+$('m2s').value,sc=+$('scalar').value;$('m1bv').textContent=m1b;$('m1sv').textContent=m1s;$('m2bv').textContent=m2b;$('m2sv').textContent=m2s;$('scalarv').textContent=sc;const c1=cost(m1b,m1s),c2=cost(m2b,m2s);$('c1').textContent=c1;$('c2').textContent=c2;$('b1b').style.width=Math.abs(m1b)*16+'px';$('b1s').style.width=Math.abs(m1s)*16+'px';$('b2b').style.width=Math.abs(m2b)*16+'px';$('b2s').style.width=Math.abs(m2s)*16+'px';const cs=cost(m1b+m2b,m1s+m2s);$('csum').textContent=cs;$('csumbound').textContent=c1+c2;$('tri-check').textContent=cs<=c1+c2?'✓ Holds':'✗ Violated';$('tri-check').style.color=cs<=c1+c2?'#6bcb77':'#ff6b6b';const cn=cost(-m1b,-m1s);$('cneg').textContent=cn;$('cpos').textContent=c1;$('neg-check').textContent=cn===c1?'✓ Holds':'✗ Violated';$('neg-check').style.color=cn===c1?'#6bcb77':'#ff6b6b';const meetB=Math.min(m1b,m2b),meetS=Math.min(m1s,m2s);const joinB=Math.max(m1b,m2b),joinS=Math.max(m1s,m2s);$('meetv').textContent=meetB+', '+meetS;$('joinv').textContent=joinB+', '+joinS;const cm=cost(meetB,meetS),cj=cost(joinB,joinS);$('cmeet').textContent=cm;$('cjoin').textContent=cj;const lhs=cm+cj,rhs=c1+c2;$('lhs').textContent=lhs;$('rhs').textContent=rhs;$('lattice-check').textContent=lhs===rhs?'✓ Identity holds!':'✗ Violated';$('lattice-check').style.color=lhs===rhs?'#6bcb77':'#ff6b6b';$('sv').textContent=sc;$('sv2').textContent=sc;const chl=cost(sc*m1b,sc*m1s),chr=Math.abs(sc)*c1;$('chom_l').textContent=chl;$('chom_r').textContent=chr;$('hom-check').textContent=chl===chr?'✓ Holds':'✗ Violated';$('hom-check').style.color=chl===chr?'#6bcb77':'#ff6b6b'}ids.forEach(id=>$(id).addEventListener('input',update));update()</script></body></html>"
    },
    {
      "title": "Voice-Swap & Consonance Map",
      "description": "Visualize which intervals are consonant, how negation maps them, and the voice-swap asymmetry on the chromatic circle.",
      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Voice-Swap & Consonance Map</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:30px;min-height:100vh}h1{font-size:1.5em;margin-bottom:5px;color:#ffd93d}h2{font-size:.85em;color:#888;margin-bottom:25px;font-weight:normal;text-align:center;max-width:600px}canvas{border-radius:12px;cursor:pointer}.info{background:#1a1a3a;border-radius:12px;padding:16px 24px;margin-top:20px;max-width:550px;text-align:center;border:1px solid #333;font-size:.95em;line-height:1.5}.highlight{color:#ffd93d;font-weight:bold}.broken{color:#ff6b6b;font-weight:bold}</style></head><body><h1>The Chromatic Circle: Consonance & Voice-Swap</h1><h2>Hover over intervals to see their properties. The involution i ↦ −i (mod 12) swaps bass and soprano — but does it preserve consonance?</h2><canvas id='circle' width='500' height='500'></canvas><div class='info' id='info'>Hover over an interval class on the circle to explore.</div><script>const C=document.getElementById('circle'),ctx=C.getContext('2d'),W=500,H=500,CX=W/2,CY=H/2,R=190,r=30;const CONSONANT=new Set([0,3,4,7,8,9]),PERFECT=new Set([0,7]);const names=['Unison/Oct','min 2nd','Maj 2nd','min 3rd','Maj 3rd','Perf 4th','Tritone','Perf 5th','min 6th','Maj 6th','min 7th','Maj 7th'];const scores=[8,1,2,5,5,6,0,7,4,4,1,1];let hovered=null;function pos(i){const a=-Math.PI/2+i*2*Math.PI/12;return{x:CX+R*Math.cos(a),y:CY+R*Math.sin(a)}}function draw(){ctx.clearRect(0,0,W,H);ctx.strokeStyle='rgba(255,255,255,0.05)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(CX,CY,R,0,2*Math.PI);ctx.stroke();if(hovered!==null){const neg=(12-hovered)%12;const p1=pos(hovered),p2=pos(neg);ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.strokeStyle='rgba(255,217,61,0.4)';ctx.lineWidth=2;ctx.setLineDash([5,5]);ctx.stroke();ctx.setLineDash([])}for(let i=0;i<12;i++){const{x,y}=pos(i);const isCons=CONSONANT.has(i);const isPerf=PERFECT.has(i);const isHov=hovered===i;const isNeg=hovered!==null&&(12-hovered)%12===i;let fillColor;if(isPerf)fillColor=isHov?'#ff4444':'#cc3333';else if(isCons)fillColor=isHov?'#44dd66':'#339944';else fillColor=isHov?'#555':'#333';ctx.beginPath();ctx.arc(x,y,isHov||isNeg?r+4:r,0,2*Math.PI);ctx.fillStyle=fillColor;ctx.fill();if(isNeg&&hovered!==i){ctx.strokeStyle='#ffd93d';ctx.lineWidth=3;ctx.stroke()}ctx.fillStyle=isHov?'#fff':isCons?'rgba(255,255,255,0.9)':'rgba(255,255,255,0.4)';ctx.font=(isHov?'bold ':'')+' 13px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(i+'',x,y-7);ctx.font='9px sans-serif';ctx.fillStyle=isCons?'rgba(255,255,255,0.7)':'rgba(255,255,255,0.3)';ctx.fillText(names[i].length>8?names[i].substring(0,7)+'.':names[i],x,y+8)}ctx.fillStyle='rgba(255,255,255,0.15)';ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText('i ↦ −i mod 12',CX,CY-10);ctx.fillText('(voice swap)',CX,CY+8)}function updateInfo(){const el=document.getElementById('info');if(hovered===null){el.innerHTML='Hover over an interval class on the circle to explore.';return}const i=hovered;const neg=(12-i)%12;const isCons=CONSONANT.has(i);const isPerf=PERFECT.has(i);const negCons=CONSONANT.has(neg);let html='<strong>'+names[i]+' ('+i+' semitones)</strong><br>';html+='Consonance score: '+scores[i]+'/8 · ';if(isPerf)html+='<span class=\"highlight\">Perfect consonance</span>';else if(isCons)html+='<span style=\"color:#6bcb77;font-weight:bold\">Imperfect consonance</span>';else html+='<span style=\"color:#888\">Dissonance</span>';html+='<br><br>';html+='Voice swap: '+i+' ↦ −'+i+' ≡ '+neg+' mod 12 = <strong>'+names[neg]+'</strong><br>';if(negCons){html+='Negation is <span style=\"color:#6bcb77\">consonant</span> ✓ — consonance preserved.'}else{html+='Negation is <span class=\"broken\">dissonant</span> ✗ — <span class=\"broken\">consonance broken!</span>'}if(i===7){html+='<br><br><em style=\"color:#ffd93d\">This is the key asymmetry: the perfect fifth (7) maps to the perfect fourth (5), which is NOT consonant in first-species counterpoint. The bass voice has a structurally privileged role.</em>'}el.innerHTML=html}C.addEventListener('mousemove',e=>{const rect=C.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let found=null;for(let i=0;i<12;i++){const{x,y}=pos(i);const dx=x-mx,dy=y-my;if(dx*dx+dy*dy<(r+5)*(r+5)){found=i;break}}if(found!==hovered){hovered=found;draw();updateInfo()}});C.addEventListener('mouseleave',()=>{hovered=null;draw();updateInfo()});draw()</script></body></html>"
