      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.5em;margin-bottom:5px;color:#7eb8ff}h2{font-size:.95em;font-weight:normal;color:#888;margin-bottom:20px}.container{display:flex;gap:30px;flex-wrap:wrap;justify-content:center;align-items:flex-start}canvas{border-radius:12px;background:#12122a;cursor:pointer}.info-panel{background:#16163a;border-radius:12px;padding:20px;min-width:280px;max-width:340px;border:1px solid #2a2a5a}.info-panel h3{color:#7eb8ff;margin-bottom:10px;font-size:1.1em}.info-panel .stat{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #1e1e4a}.info-panel .stat:last-child{border-bottom:none}.stat-label{color:#aaa}.stat-value{color:#fff;font-weight:600}.perfect{color:#ff6b6b}.imperfect{color:#51cf66}.legend{display:flex;gap:15px;margin:15px 0;font-size:.85em}.legend-item{display:flex;align-items:center;gap:5px}.legend-dot{width:12px;height:12px;border-radius:50%}</style></head><body><h1>The Counterpoint Quiver</h1><h2>Voice leadings between consonant intervals in 12-TET</h2><div class=\"container\"><canvas id=\"quiver\" width=\"520\" height=\"520\"></canvas><div class=\"info-panel\"><h3 id=\"panel-title\">Click a node to explore</h3><div class=\"legend\"><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#ff6b6b\"></div><span>Perfect</span></div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#51cf66\"></div><span>Imperfect</span></div></div><div id=\"panel-content\"><p style=\"color:#888;font-size:.9em\">The quiver has 6 vertices (consonant intervals) and 410 directed edges (permitted voice leadings). Perfect consonances are bottlenecked: 61 incoming edges vs 72 for imperfect.</p></div></div></div><script>const canvas=document.getElementById('quiver'),ctx=canvas.getContext('2d'),W=520,H=520,CX=W/2,CY=H/2,R=180;const intervals=[{id:0,name:'Unison',short:'P1',perfect:true},{id:3,name:'Minor 3rd',short:'m3',perfect:false},{id:4,name:'Major 3rd',short:'M3',perfect:false},{id:7,name:'Perfect 5th',short:'P5',perfect:true},{id:8,name:'Minor 6th',short:'m6',perfect:false},{id:9,name:'Major 6th',short:'M6',perfect:false}];const N=12,consonant=new Set([0,3,4,7,8,9]),perfect=new Set([0,7]);function homCount(i,j){if(i===j)return perfect.has(i)?1:12;return 12;}intervals.forEach((iv,idx)=>{const angle=-Math.PI/2+idx*(2*Math.PI/6);iv.x=CX+R*Math.cos(angle);iv.y=CY+R*Math.sin(angle);});let selected=null;function draw(){ctx.clearRect(0,0,W,H);intervals.forEach((src,si)=>{intervals.forEach((tgt,ti)=>{if(si===ti)return;const count=homCount(src.id,tgt.id);const dx=tgt.x-src.x,dy=tgt.y-src.y,len=Math.sqrt(dx*dx+dy*dy);const nx=-dy/len,ny=dx/len;const off=8;const mx=(src.x+tgt.x)/2+nx*off*1.5,my=(src.y+tgt.y)/2+ny*off*1.5;const alpha=selected===null?0.25:(selected===si?0.7:0.08);ctx.beginPath();ctx.moveTo(src.x+nx*off,src.y+ny*off);ctx.quadraticCurveTo(mx,my,tgt.x+nx*off,tgt.y+ny*off);const isToPerf=tgt.perfect;ctx.strokeStyle=isToPerf?`rgba(255,107,107,${alpha})`:`rgba(81,207,102,${alpha})`;ctx.lineWidth=Math.max(1,count/4);ctx.stroke();if(selected===si){const t=0.75;const ax=(1-t)*((1-t)*(src.x+nx*off)+t*mx)+t*((1-t)*mx+t*(tgt.x+nx*off));const ay=(1-t)*((1-t)*(src.y+ny*off)+t*my)+t*((1-t)*my+t*(tgt.y+ny*off));const adx=2*(1-t)*(mx-(src.x+nx*off))+2*t*((tgt.x+nx*off)-mx);const ady=2*(1-t)*(my-(src.y+ny*off))+2*t*((tgt.y+ny*off)-my);const al=Math.sqrt(adx*adx+ady*ady);const ux=adx/al,uy=ady/al;ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(ax-ux*10+uy*5,ay-uy*10-ux*5);ctx.lineTo(ax-ux*10-uy*5,ay-uy*10+ux*5);ctx.closePath();ctx.fillStyle=isToPerf?'rgba(255,107,107,0.8)':'rgba(81,207,102,0.8)';ctx.fill();}});});intervals.forEach((iv,idx)=>{const isPerf=iv.perfect;const isSel=selected===idx;const radius=isSel?32:26;ctx.beginPath();ctx.arc(iv.x,iv.y,radius,0,2*Math.PI);const grad=ctx.createRadialGradient(iv.x,iv.y,0,iv.x,iv.y,radius);if(isPerf){grad.addColorStop(0,'#ff8a8a');grad.addColorStop(1,'#cc4444');}else{grad.addColorStop(0,'#6de08a');grad.addColorStop(1,'#2d8a4e');}ctx.fillStyle=grad;ctx.fill();if(isSel){ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke();}ctx.fillStyle='#fff';ctx.font=`bold ${isSel?15:13}px 'Segoe UI',sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(iv.short,iv.x,iv.y);ctx.fillStyle='rgba(255,255,255,0.5)';ctx.font='11px sans-serif';ctx.fillText(iv.name,iv.x,iv.y+radius+14);if(isPerf){ctx.fillStyle='rgba(255,107,107,0.4)';ctx.font='10px sans-serif';ctx.fillText('perfect',iv.x,iv.y+radius+27);}});if(selected!==null){const iv=intervals[selected];intervals.forEach((tgt,ti)=>{if(ti===selected)return;const count=homCount(iv.id,tgt.id);const mx=(iv.x+tgt.x)/2,my=(iv.y+tgt.y)/2-15;ctx.fillStyle='rgba(255,255,255,0.7)';ctx.font='bold 11px sans-serif';ctx.textAlign='center';});}}function updatePanel(idx){const panel=document.getElementById('panel-content');const title=document.getElementById('panel-title');if(idx===null){title.textContent='Click a node to explore';panel.innerHTML='<p style=\"color:#888;font-size:.9em\">The quiver has 6 vertices (consonant intervals) and 410 directed edges (permitted voice leadings). Perfect consonances are bottlenecked: 61 incoming edges vs 72 for imperfect.</p>';return;}const iv=intervals[idx];title.textContent=`${iv.name} (${iv.short})`;let totalOut=0,totalIn=0;let html=`<div class=\"stat\"><span class=\"stat-label\">Type</span><span class=\"stat-value ${iv.perfect?'perfect':'imperfect'}\">${iv.perfect?'Perfect':'Imperfect'}</span></div>`;html+=`<div class=\"stat\"><span class=\"stat-label\">Self-loops</span><span class=\"stat-value\">${iv.perfect?'1 (identity only)':'12 (all parallel motions)'}</span></div>`;html+='<div style=\"margin:12px 0 6px;color:#7eb8ff;font-size:.9em\">Outgoing edges →</div>';intervals.forEach((tgt,ti)=>{const c=homCount(iv.id,tgt.id);totalOut+=c;html+=`<div class=\"stat\"><span class=\"stat-label\">→ ${tgt.short}</span><span class=\"stat-value\">${c}</span></div>`;});html+=`<div class=\"stat\" style=\"border-top:2px solid #2a2a5a;margin-top:4px\"><span class=\"stat-label\">Total out</span><span class=\"stat-value\">${totalOut}</span></div>`;html+='<div style=\"margin:12px 0 6px;color:#7eb8ff;font-size:.9em\">Incoming edges ←</div>';intervals.forEach((src,si)=>{const c=homCount(src.id,iv.id);totalIn+=c;html+=`<div class=\"stat\"><span class=\"stat-label\">← ${src.short}</span><span class=\"stat-value\">${c}</span></div>`;});html+=`<div class=\"stat\" style=\"border-top:2px solid #2a2a5a;margin-top:4px\"><span class=\"stat-label\">Total in</span><span class=\"stat-value\">${totalIn} ${iv.perfect?'(bottlenecked!)':''}</span></div>`;panel.innerHTML=html;}canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let clicked=null;intervals.forEach((iv,idx)=>{const dx=mx-iv.x,dy=my-iv.y;if(dx*dx+dy*dy<35*35)clicked=idx;});selected=clicked===selected?null:clicked;draw();updatePanel(selected);});draw();</script></body></html>"
