itions[si].y,tx=positions[ti].x,ty=positions[ti].y;const mx=(sx+tx)/2,my=(sy+ty)/2;const dx=tx-sx,dy=ty-sy,len=Math.sqrt(dx*dx+dy*dy);const nx=-dy/len*30,ny=dx/len*30;const cpx=mx+nx,cpy=my+ny;let alpha=0.08,width=1,color='#334';if(selected!==null){if(si===selected){alpha=0.7;width=2;color=t.perfect?'#ff6b9d':'#60a5fa'}else if(ti===selected){alpha=0.5;width=1.5;color=s.perfect?'#ff6b9d88':'#60a5fa88'}else{alpha=0.03}}ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(cpx,cpy,tx,ty);ctx.strokeStyle=color;ctx.globalAlpha=alpha;ctx.lineWidth=width;ctx.stroke();ctx.globalAlpha=1;if((si===selected||ti===selected)&&selected!==null){const at=0.75;const ax=(1-at)*(1-at)*sx+2*(1-at)*at*cpx+at*at*tx;const ay=(1-at)*(1-at)*sy+2*(1-at)*at*cpy+at*at*ty;const adx=2*(1-at)*(cpx-sx)+2*at*(tx-cpx);const ady=2*(1-at)*(cpy-sy)+2*at*(ty-cpy);const angle=Math.atan2(ady,adx);if(si===selected){ctx.globalAlpha=alpha;ctx.beginPath();ctx.moveTo(ax+8*Math.cos(angle),ay+8*Math.sin(angle));ctx.lineTo(ax-6*Math.cos(angle-0.4),ay-6*Math.sin(angle-0.4));ctx.lineTo(ax-6*Math.cos(angle+0.4),ay-6*Math.sin(angle+0.4));ctx.fillStyle=color;ctx.fill();ctx.globalAlpha=1}}})});intervals.forEach((iv,i)=>{const x=positions[i].x,y=positions[i].y;const isSelected=selected===i;const selfLoops=homSets[iv.id+','+iv.id];if(selfLoops>0){const loopR=isSelected?22:16;ctx.beginPath();ctx.arc(x,y-loopR-18,loopR,0,Math.PI*2);ctx.strokeStyle=iv.perfect?'#ff6b9d':'#60a5fa';ctx.globalAlpha=isSelected?0.6:0.15;ctx.lineWidth=isSelected?2:1;ctx.stroke();ctx.globalAlpha=1;if(isSelected){ctx.font='11px monospace';ctx.fillStyle='#aaa';ctx.textAlign='center';ctx.fillText(selfLoops+' loop'+(selfLoops>1?'s':''),x,y-loopR-38)}}const r=isSelected?28:22;const grad=ctx.createRadialGradient(x,y,0,x,y,r);if(iv.perfect){grad.addColorStop(0,'#ff8fb8');grad.addColorStop(1,'#ff6b9d')}else{grad.addColorStop(0,'#80b8ff');grad.addColorStop(1,'#60a5fa')}ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=grad;ctx.globalAlpha=isSelected?1:0.85;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=isSelected?'#fff':'transparent';ctx.lineWidth=2;ctx.stroke();ctx.font='bold 12px sans-serif';ctx.fillStyle='#000';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(iv.short,x,y);ctx.font='11px sans-serif';ctx.fillStyle='#bbb';ctx.fillText(iv.name,x,y+r+14)});ctx.font='11px monospace';ctx.fillStyle='#555';ctx.textAlign='left';ctx.fillText('410 edges · 6 vertices · strongly connected',10,H-10)}function updateInfo(){const el=document.getElementById('selected');if(selected===null){el.innerHTML='<p style=\"margin-top:12px;color:#aaa\">Click a vertex to see details.</p>';return}const iv=intervals[selected];let html='<h3 style=\"margin-top:16px\">'+iv.name+' ('+iv.id+' semitones)</h3>';html+='<div class=\"stat\"><span class=\"label\">Type</span><span class=\"value\">'+(iv.perfect?'Perfect':'Imperfect')+'</span></div>';const selfLoops=homSets[iv.id+','+iv.id];html+='<div class=\"stat\"><span class=\"label\">Self-loops</span><span class=\"value\">'+selfLoops+'</span></div>';let outTotal=0,inTotal=0;html+='<h3 style=\"margin-top:12px\">Outgoing</h3>';intervals.forEach(t=>{const c=homSets[iv.id+','+t.id];outTotal+=c;html+='<div class=\"stat\"><span class=\"label\">→ '+t.short+'</span><span class=\"value\">'+c+'</span></div>'});html+='<div class=\"stat\" style=\"border-top:2px solid #2a2a4a\"><span class=\"label\">Total out</span><span class=\"value\" style=\"color:#c084fc\">'+outTotal+'</span></div>';html+='<h3 style=\"margin-top:12px\">Incoming</h3>';intervals.forEach(s=>{const c=homSets[s.id+','+iv.id];inTotal+=c;html+='<div class=\"stat\"><span class=\"label\">'+s.short+' →</span><span class=\"value\">'+c+'</span></div>'});html+='<div class=\"stat\" style=\"border-top:2px solid #2a2a4a\"><span class=\"label\">Total in</span><span class=\"value\" style=\"color:#c084fc\">'+inTotal+'</span></div>';el.innerHTML=html}cv.addEventListener('click',e=>{const rect=cv.getBoundingClientRect();const mx=e.clientX-rect.left,m