on></div><div class=\"result\"><strong>Consonant set C = {0, 3, 4, 7, 8, 9}</strong><br><strong>Negated set −C = {0, 3, 4, <span class=\"highlight\">5</span>, 8, 9}</strong><br><br>The <span class=\"ok\">perfect fifth (7)</span> maps to the <span class=\"highlight\">perfect fourth (5) — DISSONANT</span><br>All other consonances map to consonances.<br><br>Symmetric difference: <span class=\"highlight\">{5, 7}</span> — the fourth/fifth pair.<br>This asymmetry means bass and soprano are <em>not</em> interchangeable.</div><script>const names=['P1','m2','M2','m3','M3','P4','TT','P5','m6','M6','m7','M7'];const consonant=new Set([0,3,4,7,8,9]);const perfect=new Set([0,7]);let animProgress=0;let animating=false;let animDir=1;function drawClock(id,highlights,negMap,progress){const c=document.getElementById(id),ctx=c.getContext('2d'),W=c.width,H=c.height,cx=W/2,cy=H/2,r=100;ctx.clearRect(0,0,W,H);ctx.beginPath();ctx.arc(cx,cy,r+15,0,2*Math.PI);ctx.strokeStyle='#ffffff10';ctx.lineWidth=1;ctx.stroke();for(let i=0;i<12;i++){const a=-Math.PI/2+2*Math.PI*i/12;const isCons=highlights.has(i);const isPerf=perfect.has(i);const isDissonantNew=negMap&&!consonant.has(i)&&highlights.has(i);const dotR=isCons?14:6;const dx=cx+r*Math.cos(a);const dy=cy+r*Math.sin(a);ctx.beginPath();ctx.arc(dx,dy,dotR,0,2*Math.PI);if(isDissonantNew){ctx.fillStyle=`rgba(255,107,107,${0.5+0.5*progress})`;ctx.strokeStyle='#ff6b6b';ctx.lineWidth=2;ctx.stroke()}else if(isCons){if(isPerf){ctx.fillStyle='#ff6b6b'}else{ctx.fillStyle='#4d96ff'}ctx.strokeStyle='rgba(255,255,255,0.3)';ctx.lineWidth=1;ctx.stroke()}else{ctx.fillStyle='#333'}ctx.fill();ctx.fillStyle=isCons?'#fff':(isDissonantNew?'#ff6b6b':'#666');ctx.font=`${isCons||isDissonantNew?'bold ':''} ${isCons?'10':'9'}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],dx,dy);if(isCons||isDissonantNew){ctx.fillStyle='#888';ctx.font='9px system-ui';const nlx=cx+(r+28)*Math.cos(a);const nly=cy+(r+28)*Math.sin(a);ctx.fillText(i.toString(),nlx,nly)}}}function animate(){if(!animating)return;animProgress+=0.02*animDir;if(animProgress>=1){animProgress=1;animating=false}if(animProgress<=0){animProgress=0;animating=false}const negSet=new Set();for(const v of consonant){const nv=(12-v)%12;const lv=Math.round(v+(nv-v+12)%12*animProgress)%12;negSet.add(lv)}drawClock('c1',consonant,false,0);drawClock('c2',animProgress<0.01?consonant:negSet,animProgress>0.5,animProgress);if(animating)requestAnimationFrame(animate)}document.getElementById('btnAnim').addEventListener('click',()=>{animDir=1;if(animProgress>=1)animProgress=0;animating=true;animate()});document.getElementById('btnReset').addEventListener('click',()=>{animProgress=0;animating=false;drawClock('c1',consonant,false,0);drawClock('c2',consonant,false,0)});drawClock('c1',consonant,false,0);const negC=new Set([...consonant].map(v=>(12-v)%12));drawClock('c2',negC,true,1)</script></body></html>"
