lp.y);continue;}else{ctx.fillStyle='#2a2a3a';}ctx.fill();ctx.fillStyle='#fff';ctx.font=`bold ${isCons?12:10}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(i.toString(),p.x,p.y);if(isCons){const lp={x:p.x,y:p.y+r+14};ctx.fillStyle='rgba(255,255,255,0.5)';ctx.font='10px sans-serif';ctx.fillText(names[i].split(' ')[1]||'',lp.x,lp.y);}}}const mappingsDiv=document.getElementById('mappings');let html='';[0,3,4,7,8,9].forEach(i=>{const j=(12-i)%12;const ok=consonant.has(j);html+=`<div class=\"mapping\"><span class=\"from\">${i}</span><span class=\"arrow\">↦</span><span class=\"to ${ok?'ok':'broken'}\">${j}</span><span style=\"color:#888;font-size:.8em;margin-left:5px\">${ok?'✓ consonant':'✗ dissonant!'}</span></div>`;});mappingsDiv.innerHTML=html;document.getElementById('toggle').addEventListener('click',function(){showMapping=!showMapping;this.classList.toggle('active');this.textContent=showMapping?'Show involution mapping':'Show involution mapping';draw();});draw();</script></body></html>"
