iv><script>const NAMES=['0 P1','1 m2','2 M2','3 m3','4 M3','5 P4','6 TT','7 P5','8 m6','9 M6','10 m7','11 M7'];const CONSONANT=new Set([0,3,4,7,8,9]);const PERFECT=new Set([0,7]);const clock=document.getElementById('clock');const svgEl=document.getElementById('arrows');const info=document.getElementById('info');const R=160,cx=200,cy=200;const notes=[];for(let i=0;i<12;i++){const a=-Math.PI/2+i*2*Math.PI/12;const x=cx+R*Math.cos(a)-18;const y=cy+R*Math.sin(a)-18;const div=document.createElement('div');div.className='note '+(PERFECT.has(i)?'perfect':CONSONANT.has(i)?'consonant':'dissonant');div.style.left=x+'px';div.style.top=y+'px';div.textContent=i;div.dataset.idx=i;clock.appendChild(div);notes.push(div);}let selected=-1;function clearHL(){notes.forEach(n=>{n.classList.remove('highlight');});svgEl.innerHTML='';}function showSwap(i){clearHL();selected=i;const j=(12-i)%12;notes[i].classList.add('highlight');notes[j].classList.add('highlight');const a1=-Math.PI/2+i*2*Math.PI/12;const a2=-Math.PI/2+j*2*Math.PI/12;const x1=cx+R*Math.cos(a1),y1=cy+R*Math.sin(a1);const x2=cx+R*Math.cos(a2),y2=cy+R*Math.sin(a2);const mid=`${cx+(x1+x2)/2*0.0} ${cy+(y1+y2)/2*0.0}`;const isCons=CONSONANT.has(i);const jCons=CONSONANT.has(j);const col=(!jCons&&isCons)?'#ff4444':'#4ecdc4';if(i!==j){const dx=x2-x1,dy=y2-y1,d=Math.sqrt(dx*dx+dy*dy);const cpx=(x1+x2)/2+(y1-y2)*0.3,cpy=(y1+y2)/2+(x2-x1)*0.3;svgEl.innerHTML=`<defs><marker id=\"ah\" markerWidth=\"8\" markerHeight=\"6\" refX=\"8\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"${col}\"/></marker></defs><path d=\"M${x1} ${y1} Q${cpx} ${cpy} ${x2} ${y2}\" stroke=\"${col}\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#ah)\" stroke-dasharray=\"6 3\"/>`;}const srcName=NAMES[i];const tgtName=NAMES[j];const preserved=CONSONANT.has(j);info.innerHTML=`<b>ι(${i}) = ${j}</b><br>${srcName} → ${tgtName}<br>${preserved?'<span style=\"color:#4ecdc4\">✓ Consonance preserved</span>':'<span style=\"color:#ff4444\">✗ Consonance 