onst p1=getPos(selected),p2=getPos(neg);ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);const preserved=consonant.has(selected)&&consonant.has(neg);ctx.strokeStyle=preserved?'#4ecdc4':'#ff6b6b';ctx.lineWidth=3;ctx.setLineDash([8,4]);ctx.stroke();ctx.setLineDash([]);const mx=(p1.x+p2.x)/2,my=(p1.y+p2.y)/2;ctx.fillStyle=preserved?'#4ecdc4':'#ff6b6b';ctx.font='bold 12px sans-serif';ctx.fillText(preserved?'✓ preserved':'✗ broken!',mx,my-15)}}function animate(){if(!animating)return;ctx.clearRect(0,0,W,H);animT+=.008;if(animT>1)animT=0;ctx.strokeStyle='#222';ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,R,0,2*Math.PI);ctx.stroke();const swapPairs=[[0,0],[3,9],[4,8],[7,5]];swapPairs.forEach(([a,b])=>{if(a===b)return;const pa=getPos(a),pb=getPos(b);ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);const broken=!consonant.has(b);ctx.strokeStyle=broken?'rgba(255,107,107,0.4)':'rgba(78,205,196,0.3)';ctx.lineWidth=2;ctx.setLineDash(broken?[5,5]:[]);ctx.stroke();ctx.setLineDash([]);const t=animT;const mx=pa.x+(pb.x-pa.x)*t,my=pa.y+(pb.y-pa.y)*t;ctx.beginPath();ctx.arc(mx,my,6,0,2*Math.PI);ctx.fillStyle=broken?'#ff6b6b':'#4ecdc4';ctx.fill()});for(let i=0;i<12;i++){const p=getPos(i);const r=16;ctx.beginPath();ctx.arc(p.x,p.y,r,0,2*Math.PI);if(perfect.has(i)){ctx.fillStyle='#cc3333'}else if(consonant.has(i)){ctx.fillStyle='#2a9d8f'}else{ctx.fillStyle='#333'}ctx.fill();ctx.strokeStyle=consonant.has(i)?'#666':'#444';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],p.x,p.y)}requestAnimationFrame(animate)}canvas.addEventListener('click',e=>{if(mode==='swap')return;const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let hit=-1;for(let i=0;i<12;i++){const p=getPos(i);if(Math.hypot(mx-p.x,my-p.y)<22)hit=i}selected=hit===selected?-1:hit;if(selected>=0){const neg=(12-selected)%12;const preserved=consonant.has(selected)&&consona