itions[si].y,tx=positions[ti].x,ty=positions[ti].y;const mx=(sx+tx)/2,my=(sy+ty)/2;const dx=tx-sx,dy=ty-sy,len=Math.sqrt(dx*dx+dy*dy);const nx=-dy/len*30,ny=dx/len*30;const cpx=mx+nx,cpy=my+ny;let alpha=0.08,width=1,color='#334';if(selected!==null){if(si===selected){alpha=0.7;width=2;color=t.perfect?'#ff6b9d':'#60a5fa'}else if(ti===selected){alpha=0.5;width=1.5;color=s.perfect?'#ff6b9d88':'#60a5fa88'}else{alpha=0.03}}ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(cpx,cpy,tx,ty);ctx.strokeStyle=color;ctx.globalAlpha=alpha;ctx.lineWidth=width;ctx.stroke();ctx.globalAlpha=1;if((si===selected||ti===selected)&&selected!==null){const at=0.75;const ax=(1-at)*(1-at)*sx+2*(1-at)*at*cpx+at*at*tx;const ay=(1-at)*(1-at)*sy+2*(1-at)*at*cpy+at*at*ty;const adx=2*(1-at)*(cpx-sx)+2*at*(tx-cpx);const ady=2*(1-at)*(cpy-sy)+2*at*(ty-cpy);const angle=Math.atan2(ady,adx);if(si===selected){ctx.globalAlpha=alpha;ctx.beginPath();ctx.moveTo(ax+8*Math.cos(angle),ay+8*Math.sin(angle));ctx.lineTo(ax-6*Math.cos(angle-0.4),ay-6*Math.sin(angle-0.4));ctx.lineTo(ax-6*Math.cos(angle+0.4),ay-6*Math.sin(angle+0.4));ctx.fillStyle=color;ctx.fill();ctx.globalAlpha=1}}})});intervals.forEach((iv,i)=>{const x=positions[i].x,y=positions[i].y;const isSelected=selected===i;const selfLoops=homSets[iv.id+','+iv.id];if(selfLoops>0){const loopR=isSelected?22:16;ctx.beginPath();ctx.arc(x,y-loopR-18,loopR,0,Math.PI*2);ctx.strokeStyle=iv.perfect?'#ff6b9d':'#60a5fa';ctx.globalAlpha=isSelected?0.6:0.15;ctx.lineWidth=isSelected?2:1;ctx.stroke();ctx.globalAlpha=1;if(isSelected){ctx.font='11px monospace';ctx.fillStyle='#aaa';ctx.textAlign='center';ctx.fillText(selfLoops+' loop'+(selfLoops>1?'s':''),x,y-loopR-38)}}const r=isSelected?28:22;const grad=ctx.createRadialGradient(x,y,0,x,y,r);if(iv.perfect){grad.addColorStop(0,'#ff8fb8');grad.addColorStop(1,'#ff6b9d')}else{grad.addColorStop(0,'#80b8ff');grad.addColorStop(1,'#60a5fa')}ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=grad;ctx.globalAlpha=isSelected?