ntity for Voice Leading</h1><h2>cost(m₁ ⊓ m₂) + cost(m₁ ⊔ m₂) = cost(m₁) + cost(m₂)</h2><div class='main'><div class='panel'><h3 style='color:#ff6b9d'>Motion m₁</h3><div id='s1'></div><h3 style='color:#60a5fa;margin-top:16px'>Motion m₂</h3><div id='s2'></div><h3 style='color:#c084fc;margin-top:16px'>Computed</h3><div class='cost-display'><div class='cost-box'><span class='clabel'>m₁ ⊓ m₂ (meet)</span><span class='cval' id='meet-val'></span></div><div class='cost-box'><span class='clabel'>m₁ ⊔ m₂ (join)</span><span class='cval' id='join-val'></span></div></div></div><div class='panel' style='min-width:360px'><h3>Voice Components</h3><div style='display:flex;gap:20px'><div><div class='bar-container' id='bars1'></div><div style='text-align:center;font-size:.8em;color:#999'>m₁ components</div></div><div><div class='bar-container' id='bars2'></div><div style='text-align:center;font-size:.8em;color:#999'>m₂ components</div></div><div><div class='bar-container' id='bars-meet'></div><div style='text-align:center;font-size:.8em;color:#999'>meet</div></div><div><div class='bar-container' id='bars-join'></div><div style='text-align:center;font-size:.8em;color:#999'>join</div></div></div><h3 style='margin-top:16px'>Costs</h3><div class='cost-display'><div class='cost-box'><span class='clabel'>‖m₁‖₁</span><span class='cval' id='c1' style='color:#ff6b9d'></span></div><div class='cost-box'><span class='clabel'>‖m₂‖₁</span><span class='cval' id='c2' style='color:#60a5fa'></span></div><div class='cost-box'><span class='clabel'>‖m₁⊓m₂‖₁</span><span class='cval' id='cm' style='color:#a0f0a0'></span></div><div class='cost-box'><span class='clabel'>‖m₁⊔m₂‖₁</span><span class='cval' id='cj' style='color:#f0d060'></span></div></div><div class='equation' id='eq'></div><div class='equation' id='tri' style='font-size:.9em'></div></div></div><script>const NV=4;const labels=['S','A','T','B'];let m1=new Array(NV).fill(0),m2=new Array(NV).fill(0);function makeSliders(containerId,arr,color){const c=document.getElementById(containerId);c.innerHTML='';arr.forEach((_,i)=>{const row=document.createElement('div');row.className='slider-row';const lbl=document.createElement('label');lbl.textContent=labels[i];const inp=document.createElement('input');inp.type='range';inp.min=-8;inp.max=8;inp.value=arr[i];inp.style.accentColor=color;const val=document.createElement('span');val.className='val';val.textContent=arr[i];inp.addEventListener('input',()=>{arr[i]=parseInt(inp.value);val.textContent=arr[i];update()});row.appendChild(lbl);row.appendChild(inp);row.appendChild(val);c.appendChild(row)})}function cost(a){return a.reduce((s,v)=>s+Math.abs(v),0)}function meet(a,b){return a.map((v,i)=>Math.min(v,b[i]))}function join(a,b){return a.map((v,i)=>Math.max(v,b[i]))}function makeBars(containerId,arr,color){const c=document.getElementById(containerId);c.innerHTML='';const maxH=100;arr.forEach(v=>{const bar=document.createElement('div');bar.className='bar';const h=Math.abs(v)*10;bar.style.height=Math.max(h,2)+'px';bar.style.background=v>=0?color:(color+'88');bar.style.border=v<0?'1px dashed '+color:'none';const sp=document.createElement('span');sp.textContent=v;bar.appendChild(sp);c.appendChild(bar)})}function update(){const mt=meet(m1,m2),jn=join(m1,m2);const c1v=cost(m1),c2v=cost(m2),cmv=cost(mt),cjv=cost(jn);document.getElementById('c1').textContent=c1v;document.getElementById('c2').textContent=c2v;document.getElementById('cm').textContent=cmv;document.getElementById('cj').textContent=cjv;document.getElementById('meet-val').textContent='['+mt.join(', ')+']';document.getElementById('join-val').textContent='['+jn.join(', ')+']';const lhs=cmv+cjv,rhs=c1v+c2v;const eq=document.getElementById('eq');eq.textContent=cmv+' + '+cjv+' = '+lhs+'   '+(lhs===rhs?'=':'≠')+'   '+c1v+' + '+c2v+' = '+rhs;eq.className='equation '+(lhs===rhs?'eq-true':'eq-false');const triOk=cost(m1.map((v,i)=>v+m2[i]))<=c1v+c2v;const tri=document.getElementById('tri');tri.textContent='△ inequality: ‖m₁+m₂‖₁ = '+cost(m1.map((v,i)=>v+m2[i]))+' ≤ '+c1v+' + '+c2v+' = '+(c1v+c2v)+(triOk?' ✓':' ✗');tri.className='equation '+(triOk?'eq-true':'eq-false');makeBars('bars1',m1,'#ff6b9d');makeBars('bars2',m2,'#60a5fa');makeBars('bars-meet',mt,'#6f6');makeBars('bars-join',jn,'#fd0')}m1=[3,-2,5,-1];m2=[1,4,-3,2];makeSliders('s1',m1,'#ff6b9d');makeSliders('s2',m2,'#60a5fa');update()</script></body></html>"
