','Perfect 4th','Tritone','Perfect 5th','Minor 6th','Major 6th','Minor 7th','Major 7th'];const scores=[8,1,2,5,5,6,0,7,4,4,1,1];const consonant=new Set([0,3,4,7,8,9]);const perfect=new Set([0,7]);let showNeg=false,showCons=false;function scoreColor(s){if(s>=7)return'#ff6b9d';if(s>=5)return'#c084fc';if(s>=4)return'#60a5fa';if(s>=2)return'#4a6a8a';return'#2a3a4a'}function draw(){ctx.clearRect(0,0,W,H);const positions=[];for(let i=0;i<12;i++){const a=-Math.PI/2+i*Math.PI/6;positions.push({x:CX+R*Math.cos(a),y:CY+R*Math.sin(a)})}if(showNeg){for(let i=0;i<12;i++){const j=(12-i)%12;if(i>=j)continue;const p1=positions[i],p2=positions[j];const cons_i=consonant.has(i),cons_j=consonant.has(j);const breaks=cons_i!==cons_j;ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.strokeStyle=breaks?'#ff4444':'#2a4a2a';ctx.lineWidth=breaks?3:1.5;ctx.globalAlpha=breaks?0.8:0.3;ctx.setLineDash(breaks?[]:[5,5]);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;if(breaks){const mx=(p1.x+p2.x)/2,my=(p1.y+p2.y)/2;ctx.font='bold 11px sans-serif';ctx.fillStyle='#ff4444';ctx.textAlign='center';ctx.fillText('BREAKS',mx,my-6);ctx.fillText('CONSONANCE',mx,my+8)}}ctx.beginPath();ctx.arc(positions[6].x,positions[6].y,18,0,Math.PI*2);ctx.strokeStyle='#666';ctx.lineWidth=1;ctx.globalAlpha=0.5;ctx.stroke();ctx.globalAlpha=1;ctx.font='9px sans-serif';ctx.fillStyle='#666';ctx.textAlign='center';ctx.fillText('fixed',positions[6].x,positions[6].y+28)}for(let i=0;i<12;i++){const{x,y}=positions[i];const s=scores[i];const r=14+s*2;const isCons=consonant.has(i);const isPerf=perfect.has(i);if(showCons&&isCons){ctx.beginPath();ctx.arc(x,y,r+6,0,Math.PI*2);ctx.strokeStyle=isPerf?'#ff6b9d':'#60a5fa';ctx.lineWidth=2;ctx.globalAlpha=0.6;ctx.stroke();ctx.globalAlpha=1}const grad=ctx.createRadialGradient(x,y,0,x,y,r);const col=scoreColor(s);grad.addColorStop(0,col);grad.addColorStop(1,col+'88');ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=showCons&&!isCons?'#1a1a2a':grad;ctx.globalAlpha=showC