"></div></section><section><h3>Incoming Voice Leadings by Target Type</h3><p style=\"color:#888;font-size:.85em;margin-bottom:8px\">Total permitted voice leadings arriving at each consonant interval, summed over all 6 consonant sources.</p><div class=\"hom-chart\" id=\"hom-chart\"></div><div class=\"gap-note\" id=\"gap-note\"></div></section><script>const N=12,C=[0,3,4,7,8,9],P=new Set([0,7]);const names={0:'Unison',1:'m2',2:'M2',3:'m3',4:'M3',5:'P4',6:'Tritone',7:'P5',8:'m6',9:'M6',10:'m7',11:'M7'};function targetInt(s,b,sp){return((s+sp-b)%N+N)%N}function isPar(b,s){return b===s&&b%N!==0}function countPerm(src,tgt){let c=0;for(let b=0;b<N;b++)for(let s=0;s<N;s++)if(C.includes(src)&&C.includes(tgt)&&targetInt(src,b,s)===tgt&&!(P.has(tgt)&&isPar(b,s)))c++;return c}const md=document.getElementById('mappings');C.forEach(i=>{const neg=(N-i)%N;const isConsonant=C.includes(neg);const row=document.createElement('div');row.className=`mapping-row ${isConsonant?'ok':'fail'}`;row.innerHTML=`<span style=\"width:24px;font-weight:700\">${i}</span><span style=\"color:#888\">→</span><span style=\"width:24px;font-weight:700\">${neg}</span><span style=\"flex:1;color:#aaa\">${names[i]} → ${names[neg]}</span><span style=\"font-weight:700;color:${isConsonant?'#69db7c':'#ff6b6b'}\">${isConsonant?'✓ Consonant':'✗ Dissonant'}</span>`;md.appendChild(row)});const hc=document.getElementById('hom-chart');const totals=C.map(tgt=>({interval:tgt,name:names[tgt],total:C.reduce((s,src)=>s+countPerm(src,tgt),0),perfect:P.has(tgt)}));const maxT=Math.max(...totals.map(t=>t.total));totals.forEach((t,i)=>{const col=document.createElement('div');col.style.display='flex';col.style.flexDirection='column';col.style.alignItems='center';const bar=document.createElement('div');bar.className='hom-bar';bar.style.width='80px';bar.style.background=t.perfect?'linear-gradient(to top,#993333,#ff6b6b)':'linear-gradient(to top,#2d8a3e,#69db7c)';bar.style.height='4px';const val=document.createElement('div');val.className='hom-val';val.style.color=t.perfect?'#ff6b6b':'#69db7c';val.textContent=t.total;bar.appendChild(val);const lbl=document.createElement('div');lbl.className='hom-label';lbl.textContent=t.name;col.appendChild(bar);col.appendChild(lbl);hc.appendChild(col);setTimeout(()=>{bar.style.height=`${(t.total/maxT)*140}px`},200+i*100)});const pAvg=totals.filter(t=>t.perfect).reduce((s,t)=>s+t.total,0)/totals.filter(t=>t.perfect).length;const iAvg=totals.filter(t=>!t.perfect).reduce((s,t)=>s+t.total,0)/totals.filter(t=>!t.perfect).length;document.getElementById('gap-note').innerHTML=`Perfect consonances: <strong style=\"color:#ff6b6b\">${pAvg}</strong> incoming &nbsp;|&nbsp; Imperfect: <strong style=\"color:#69db7c\">${iAvg}</strong> incoming &nbsp;|&nbsp; Gap: <strong style=\"color:#7eb8ff\">${((1-pAvg/iAvg)*100).toFixed(1)}%</strong> fewer at perfect consonances`</script></body></html>"
