,7,8,9]);const perfect=new Set([0,7]);const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];const intervalNames={0:'Unison',1:'m2',2:'M2',3:'m3',4:'M3',5:'P4',6:'Tritone',7:'P5',8:'m6',9:'M6',10:'m7',11:'M7'};const cx=230,cy=230,R=170,r=24;let selected=-1;function neg(i){return(12-i)%12}function makeCircle(){svg.innerHTML='';const defs=document.createElementNS('http://www.w3.org/2000/svg','defs');defs.innerHTML=`<marker id='ah' markerWidth='8' markerHeight='6' refX='8' refY='3' orient='auto'><path d='M0,0 L8,3 L0,6' fill='#f0883e'/></marker>`;svg.appendChild(defs);for(let i=0;i<12;i++){const a=-Math.PI/2+i*Math.PI/6;const x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);const isCons=consonant.has(i);const isPerfect=perfect.has(i);const isSelected=selected===i;const isImage=selected>=0&&neg(selected)===i;const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.style.cursor='pointer';const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.setAttribute('cx',x);circle.setAttribute('cy',y);circle.setAttribute('r',isSelected||isImage?r+4:r);circle.setAttribute('fill',isSelected?'#f0883e':isImage?(isCons?'#3fb950':'#f85149'):(isCons?(isPerfect?'#f9758390':'#79c0ff80'):'#30363d'));circle.setAttribute('stroke',isSelected?'#fff':(isImage?'#fff':'none'));circle.setAttribute('stroke-width','2');g.appendChild(circle);const t1=document.createElementNS('http://www.w3.org/2000/svg','text');t1.setAttribute('x',x);t1.setAttribute('y',y-4);t1.setAttribute('text-anchor','middle');t1.setAttribute('fill','#fff');t1.setAttribute('font-size','13');t1.setAttribute('font-weight','bold');t1.textContent=i;g.appendChild(t1);const t2=document.createElementNS('http://www.w3.org/2000/svg','text');t2.setAttribute('x',x);t2.setAttribute('y',y+11);t2.setAttribute('text-anchor','middle');t2.setAttribute('fill','#c9d1d9');t2.setAttribute('font-size','9');t2.textContent=intervalNames[i]||'';g.appendChild(t2);g.addEventListener('click',()=>{selected=selected===i?