      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}.title{font-size:1.5rem;font-weight:700;margin-bottom:4px;background:linear-gradient(90deg,#64b5f6,#ce93d8);-webkit-background-clip:text;-webkit-text-fill-color:transparent}.subtitle{font-size:.85rem;color:#888;margin-bottom:16px}.container{display:flex;gap:24px;flex-wrap:wrap;justify-content:center;max-width:1100px;width:100%}.panel{background:#12122a;border:1px solid #2a2a4a;border-radius:12px;padding:20px}.graph-panel{width:480px;height:480px;position:relative}.info-panel{width:340px;min-height:480px}.info-panel h3{font-size:1rem;color:#64b5f6;margin-bottom:10px}.info-panel .stat{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #1a1a3a;font-size:.85rem}.stat .label{color:#aaa}.stat .val{color:#fff;font-weight:600}.legend{margin-top:16px;font-size:.8rem}.legend-item{display:flex;align-items:center;gap:8px;margin:4px 0}.legend-dot{width:14px;height:14px;border-radius:50%}.selected-info{margin-top:16px;padding:12px;background:#1a1a3a;border-radius:8px;font-size:.85rem;min-height:120px}canvas{border-radius:8px;cursor:pointer}.matrix-panel{width:100%;max-width:820px}.matrix-panel table{width:100%;border-collapse:collapse;font-size:.8rem;text-align:center}.matrix-panel th,.matrix-panel td{padding:6px 4px;border:1px solid #2a2a4a}.matrix-panel th{background:#1a1a3a;color:#64b5f6}.matrix-panel td{color:#e0e0e0}.matrix-panel .perfect{background:#2a1a3a;color:#ce93d8;font-weight:700}.matrix-panel .imperfect{background:#1a2a2a;color:#64b5f6}.highlight{background:#3a2a1a !important;color:#ffb74d !important}</style></head><body><div class=\"title\">The Counterpoint Quiver</div><div class=\"subtitle\">Consonant intervals connected by permitted voice leadings in 12-TET</div><div class=\"container\"><div class=\"panel graph-panel\"><canvas id=\"quiverCanvas\" width=\"480\" height=\"480\"></canvas></div><div class=\"panel info-panel\"><h3>Quiver Statistics</h3><div class=\"stat\"><span class=\"label\">Consonant intervals (vertices)</span><span class=\"val\">6</span></div><div class=\"stat\"><span class=\"label\">Total permitted voice leadings</span><span class=\"val\">410</span></div><div class=\"stat\"><span class=\"label\">Incoming to perfect cons.</span><span class=\"val\">61</span></div><div class=\"stat\"><span class=\"label\">Incoming to imperfect cons.</span><span class=\"val\">72</span></div><div class=\"stat\"><span class=\"label\">Bottleneck ratio</span><span class=\"val\">61/72 ≈ 0.847</span></div><div class=\"stat\"><span class=\"label\">Self-loops (perfect)</span><span class=\"val\">1</span></div><div class=\"stat\"><span class=\"label\">Self-loops (imperfect)</span><span class=\"val\">12</span></div><div class=\"legend\"><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#ce93d8;border:2px solid #e040fb\"></div>Perfect consonance (bottleneck)</div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#64b5f6;border:2px solid #42a5f5\"></div>Imperfect consonance</div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#333;border:2px solid #ffb74d\"></div>Edge thickness ∝ arrow count</div></div><div class=\"selected-info\" id=\"selectedInfo\">Click a node to see its voice-leading connections.</div></div></div><div class=\"panel matrix-panel\"><h3 style=\"font-size:1rem;color:#64b5f6;margin-bottom:10px\">Arrow Count Matrix (source → target)</h3><table id=\"matrixTable\"></table></div><script>const CONSONANT=[0,3,4,7,8,9];const PERFECT=new Set([0,7]);const NAMES={0:'P1 (Unison)',3:'m3 (Minor 3rd)',4:'M3 (Major 3rd)',7:'P5 (Perf. 5th)',8:'m6 (Minor 6th)',9:'M6 (Major 6th)'};const SHORT={0:'P1',3:'m3',4:'M3',7:'P5',8:'m6',9:'M6'};function countArrows(src,tgt){let c=0;for(let b=0;b<12;b++){for(let s=0;s<12;s++){let target=(src+s-b+120)%12;if(target!==tgt)continue;let parallel=(b===s)&&(b!==0);if(PERFECT.has(tgt)&&parallel)continue;c++}}return c}const MATRIX={};CONSONANT.forEach(s=>{CONSONANT.forEach(t=>{MATRIX[s+','+t]=countArrows(s,t)})});const canvas=document.getElementById('quiverCanvas');const ctx=canvas.getContext('2d');const CX=240,CY=240,R=160;const nodePositions={};CONSONANT.forEach((v,i)=>{const angle=-Math.PI/2+i*2*Math.PI/6;nodePositions[v]={x:CX+R*Math.cos(angle),y:CY+R*Math.sin(angle)}});let selectedNode=null;function draw(){ctx.clearRect(0,0,480,480);CONSONANT.forEach(src=>{CONSONANT.forEach(tgt=>{if(src===tgt)return;const count=MATRIX[src+','+tgt];const p1=nodePositions[src],p2=nodePositions[tgt];const dx=p2.x-p1.x,dy=p2.y-p1.y;const len=Math.sqrt(dx*dx+dy*dy);const nx=dx/len,ny=dy/len;const offset=4;const sx=p1.x+ny*offset,sy=p1.y-nx*offset;const ex=p2.x+ny*offset,ey=p2.y-nx*offset;const isHighlighted=selectedNode!==null&&(src===selectedNode||tgt===selectedNode);ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ex,ey);ctx.strokeStyle=isHighlighted?'rgba(255,183,77,0.7)':'rgba(100,181,246,0.15)';ctx.lineWidth=isHighlighted?Math.max(1,count/4):1;ctx.stroke();if(isHighlighted){const arrowLen=10;const mx=(sx+ex)/2,my=(sy+ey)/2;const ax=mx-arrowLen*nx+arrowLen*ny*0.4;const ay=my-arrowLen*ny-arrowLen*nx*0.4;const bx=mx-arrowLen*nx-arrowLen*ny*0.4;const by=my-arrowLen*ny+arrowLen*nx*0.4;ctx.beginPath();ctx.moveTo(mx,my);ctx.lineTo(ax,ay);ctx.moveTo(mx,my);ctx.lineTo(bx,by);ctx.strokeStyle='rgba(255,183,77,0.5)';ctx.lineWidth=1.5;ctx.stroke()}})});CONSONANT.forEach(v=>{const p=nodePositions[v];const isPerfect=PERFECT.has(v);const isSelected=v===selectedNode;const selfLoops=MATRIX[v+','+v];const radius=isSelected?28:isPerfect?22:20;if(selfLoops>1){ctx.beginPath();ctx.arc(p.x,p.y-radius-8,8,0,2*Math.PI);ctx.strokeStyle='rgba(100,181,246,0.4)';ctx.lineWidth=1;ctx.stroke()}ctx.beginPath();ctx.arc(p.x,p.y,radius,0,2*Math.PI);if(isPerfect){ctx.fillStyle=isSelected?'#e040fb':'#ce93d8';ctx.strokeStyle='#e040fb'}else{ctx.fillStyle=isSelected?'#42a5f5':'#1e88e5';ctx.strokeStyle='#42a5f5'}ctx.lineWidth=isSelected?3:2;ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.font=isSelected?'bold 13px sans-serif':'bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(SHORT[v],p.x,p.y);ctx.fillStyle='#aaa';ctx.font='10px sans-serif';ctx.fillText(selfLoops+' loop'+(selfLoops!==1?'s':''),p.x,p.y+radius+14)})}canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let clicked=null;CONSONANT.forEach(v=>{const p=nodePositions[v];const d=Math.sqrt((mx-p.x)**2+(my-p.y)**2);if(d<25)clicked=v});selectedNode=clicked===selectedNode?null:clicked;draw();updateInfo()});function updateInfo(){const el=document.getElementById('selectedInfo');if(selectedNode===null){el.innerHTML='Click a node to see its voice-leading connections.';unhighlightMatrix();return}const v=selectedNode;const isPerfect=PERFECT.has(v);let html='<strong>'+NAMES[v]+'</strong><br>';html+='Type: '+(isPerfect?'<span style=\"color:#ce93d8\">Perfect</span>':'<span style=\"color:#64b5f6\">Imperfect</span>')+'<br>';const selfLoops=MATRIX[v+','+v];html+='Self-loops: <strong>'+selfLoops+'</strong><br>';let incoming=0,outgoing=0;CONSONANT.forEach(s=>{incoming+=MATRIX[s+','+v];outgoing+=MATRIX[v+','+s]});html+='Incoming VLs: <strong>'+incoming+'</strong><br>';html+='Outgoing VLs: <strong>'+outgoing+'</strong><br><br>';html+='<span style=\"font-size:.78rem;color:#aaa\">Arrows from this node:</span><br>';CONSONANT.forEach(t=>{const c=MATRIX[v+','+t];html+='<span style=\"font-size:.78rem\">→ '+SHORT[t]+': '+c+' voice leadings</span><br>'});el.innerHTML=html;highlightMatrix(v)}function highlightMatrix(v){document.querySelectorAll('#matrixTable td, #matrixTable th').forEach(el=>el.classList.remove('highlight'));const idx=CONSONANT.indexOf(v);document.querySelectorAll('#matrixTable tr').forEach((row,ri)=>{if(ri===0){row.children[idx+1]&&row.children[idx+1].classList.add('highlight')}else if(ri===idx+1){Array.from(row.children).forEach(c=>c.classList.add('highlight'))}else{row.children[idx+1]&&row.children[idx+1].classList.add('highlight')}})}function unhighlightMatrix(){document.querySelectorAll('#matrixTable td, #matrixTable th').forEach(el=>el.classList.remove('highlight'))}function buildMatrix(){const table=document.getElementById('matrixTable');let html='<tr><th>→</th>';CONSONANT.forEach(t=>{const cls=PERFECT.has(t)?'perfect':'imperfect';html+='<th class=\"'+cls+'\">'+SHORT[t]+'</th>'});html+='<th>Row Σ</th></tr>';CONSONANT.forEach(s=>{const cls=PERFECT.has(s)?'perfect':'imperfect';html+='<tr><th class=\"'+cls+'\">'+SHORT[s]+'</th>';let rowSum=0;CONSONANT.forEach(t=>{const c=MATRIX[s+','+t];rowSum+=c;const cellCls=PERFECT.has(t)?'perfect':'imperfect';html+='<td class=\"'+cellCls+'\">'+c+'</td>'});html+='<td><strong>'+rowSum+'</strong></td></tr>'});html+='<tr><th>Col Σ</th>';let total=0;CONSONANT.forEach(t=>{let colSum=0;CONSONANT.forEach(s=>colSum+=MATRIX[s+','+t]);total+=colSum;html+='<td><strong>'+colSum+'</strong></td>'});html+='<td><strong>'+total+'</strong></td></tr>';table.innerHTML=html}buildMatrix();draw()</script></body></html>"
