class=\"panel\"><h2>Codewords</h2><button class=\"btn btn-clear\" onclick=\"clearCode()\">🗑 Clear All</button><div class=\"cw-list\" id=\"cwList\"></div></div></div><script>const A=3,L=6;let d=3,code=[],newCW=[0,0,0,0,0,0];const colors=['s0','s1','s2'];function hamming(a,b){let c=0;for(let i=0;i<L;i++)if(a[i]!==b[i])c++;return c}function renderNew(){const el=document.getElementById('newCW');el.innerHTML='';for(let i=0;i<L;i++){const s=document.createElement('div');s.className='sym '+colors[newCW[i]];s.textContent=newCW[i];s.onclick=()=>{newCW[i]=(newCW[i]+1)%A;renderNew()};el.appendChild(s)}}function updateD(){d=+document.getElementById('dSlider').value;document.getElementById('dVal').textContent=d;renderCode()}function singleton(){return Math.pow(A,L-d+1)}function renderCode(){document.getElementById('singBound').textContent=singleton();document.getElementById('codeSize').textContent=code.length;const pct=code.length/singleton()*100;document.getElementById('gaugeFill').style.width=Math.min(100,pct)+'%';document.getElementById('gaugeText').textContent=Math.round(pct)+'%';const list=document.getElementById('cwList');list.innerHTML='';for(let j=0;j<code.length;j++){const item=document.createElement('div');item.className='cw-item';let minD=Infinity;for(let k=0;k<code.length;k++){if(k!==j){const dd=hamming(code[j],code[k]);if(dd<minD)minD=dd}}item.innerHTML=`<span class=\"cw-idx\">${j}</span><span>[${code[j].join(',')}]</span><span style=\"color:#888;margin-left:auto;font-size:.8em\">min_d=${minD===Infinity?'—':minD}</span><span class=\"cw-del\" onclick=\"delCW(${j})\"> ✕</span>`;list.appendChild(item)}}function addCW(){const cw=[...newCW];for(let j=0;j<code.length;j++){if(hamming(cw,code[j])===0){showMsg('Duplicate codeword!','err');return}if(hamming(cw,code[j])<d){showMsg(`Distance to codeword ${j} is ${hamming(cw,code[j])} < d=${d}. Rejected!`,'err');return}}if(code.length>=singleton()){showMsg(`Singleton bound reached! Cannot add more than ${singleton()} codewords.`