ary)</option></select></div><div class=\"control-group\"><label>Length (L)</label><select id=\"lenSelect\"><option value=\"2\">2</option><option value=\"3\" selected>3</option><option value=\"4\">4</option></select></div><div class=\"control-group\"><label>Selected Volume</label><input id=\"volInput\" type=\"text\" value=\"000\" size=\"6\" placeholder=\"e.g. 012\"></div></div><div class=\"stats\"><div class=\"stat-card\"><div class=\"value\" id=\"libSize\">27</div><div class=\"label\">Library Size (A<sup>L</sup>)</div></div><div class=\"stat-card\"><div class=\"value\" id=\"degreeVal\">6</div><div class=\"label\">Neighbors L×(A−1)</div></div><div class=\"stat-card\"><div class=\"value\" id=\"diameterVal\">3</div><div class=\"label\">Diameter (L)</div></div><div class=\"stat-card\"><div class=\"value\" id=\"distVal\">—</div><div class=\"label\">Distance to Selected</div></div></div><canvas id=\"canvas\" width=\"800\" height=\"500\"></canvas><div class=\"volume-display\" id=\"volDisplay\"></div><div class=\"info\"><strong>Theorem (babel_degree):</strong> Every volume has exactly L×(A−1) = <span id=\"degreeFormula\"></span> Hamming neighbors.<br><strong>Theorem (babel_diameter_achieved):</strong> The maximum Hamming distance is L = <span id=\"diamFormula\"></span>, achieved by volumes differing in all positions.</div></div><script>const canvas=document.getElementById('canvas'),ctx=canvas.getContext('2d');let A=3,L=3,selectedVol='000',volumes=[],hoveredIdx=-1;function init(){A=parseInt(document.getElementById('alphaSelect').value);L=parseInt(document.getElementById('lenSelect').value);volumes=[];generateVolumes([],0);document.getElementById('libSize').textContent=Math.pow(A,L);document.getElementById('degreeVal').textContent=L*(A-1);document.getElementById('diameterVal').textContent=L;document.getElementById('degreeFormula').textContent=`${L}×${A-1} = ${L*(A-1)}`;document.getElementById('diamFormula').textContent=L;if(selectedVol.length!==L||[...selectedVol].some(c=>parseInt(c)>=A)){selectedVol='0'.repeat(L);document.getElementById('volInput').value=selectedVol}draw()}function generateVolumes(prefix,depth){if(depth===L){volumes.push(prefix.join(''));return}for(let i=0;i<A;i++)generateVolumes([...prefix,i],depth+1)}function hamming(a,b){let d=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])d++;return d}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);if(volumes.length>256){ctx.fillStyle='#6272a4';ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(`Library has ${volumes.length} volumes — showing distance histogram`,400,250);drawHistogram();return}const n=volumes.length;const cols=Math.ceil(Math.sqrt(n*1.5));const rows=Math.ceil(n/cols);const cellW=canvas.width/cols;const cellH=canvas.height/rows;const maxDist=L;volumes.forEach((v,i)=>{const col=i%cols,row=Math.floor(i/cols);const x=col*cellW+cellW/2,y=row*cellH+cellH/2;const d=hamming(v,selectedVol);const isSelected=v===selectedVol;const isNeighbor=d===1;let color;if(isSelected)color='#ff79c6';else if(isNeighbor)color='#50fa7b';else{const t=d/maxDist;color=`hsl(${240-t*180},60%,${50-t*20}%)`}const r=Math.min(cellW,cellH)*0.35;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.globalAlpha=isSelected?1:isNeighbor?0.9:0.5;ctx.fill();ctx.globalAlpha=1;if(isSelected){ctx.strokeStyle='#ff79c6';ctx.lineWidth=2;ctx.stroke()}if(n<=64){ctx.fillStyle='#f8f8f2';ctx.font=`${Math.min(10,r*0.8)}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v,x,y)}});if(hoveredIdx>=0&&hoveredIdx<n){const d=hamming(volumes[hoveredIdx],selectedVol);document.getElementById('distVal').textContent=d;document.getElementById('volDisplay').textContent=`Hovered: ${volumes[hoveredIdx]} | Distance: ${d}`}else{document.getElementById('distVal').textContent='—';document.getElementById('volDisplay').textContent=`Selected: ${selectedVol} | Click a volume or type one above`}}function drawHistogram(){const counts=new Array(L+1).fill(0);volumes.forEach(v=>{const d=hamming(v,selectedVol);counts[d]++});const maxCount=Math.max(...counts);const barW=600/(L+1);const baseY=420,maxH=300;ctx.fillStyle='#6272a4';ctx.font='12px sans-serif';ctx.textAlign='center';for(let d=0;d<=L;d++){const h=maxCount>0?(counts[d]/maxCount)*maxH:0;const x=100+d*barW;const color=d===0?'#ff79c6':d===1?'#50fa7b':`hsl(${240-d/L*180},60%,40%)`;ctx.fillStyle=color;ctx.fillRect(x+5,baseY-h,barW-10,h);ctx.fillStyle='#f8f8f2';ctx.font='11px sans-serif';ctx.fillText(counts[d],x+barW/2,baseY-h-8);ctx.fillText(`d=${d}`,x+barW/2,baseY+15)}}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=(e.clientX-rect.left)*(canvas.width/rect.width);const my=(e.clientY-rect.top)*(canvas.height/rect.height);if(volumes.length>256)return;const n=volumes.length;const cols=Math.ceil(Math.sqrt(n*1.5));const cellW=canvas.width/cols;const cellH=canvas.height/Math.ceil(n/cols);hoveredIdx=-1;volumes.forEach((v,i)=>{const col=i%cols,row=Math.floor(i/cols);const x=col*cellW+cellW/2,y=row*cellH+cellH/2;const r=Math.min(cellW,cellH)*0.35;if(Math.hypot(mx-x,my-y)<r)hoveredIdx=i});draw()});canvas.addEventListener('click',()=>{if(hoveredIdx>=0&&hoveredIdx<volumes.length){selectedVol=volumes[hoveredIdx];document.getElementById('volInput').value=selectedVol;draw()}});document.getElementById('volInput').addEventListener('input',e=>{const v=e.target.value;if(v.length===L&&[...v].every(c=>{const d=parseInt(c);return!isNaN(d)&&d<A})){selectedVol=v;draw()}});document.getElementById('alphaSelect').addEventListener('change',init);document.getElementById('lenSelect').addEventListener('change',init);init()</script></body></html>"
    },
    {
      "title": "Coding Bounds Visualizer",
      "description": "Compare the Singleton and Hamming bounds for BabelCodes as minimum distance varies.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>BabelCode Bounds</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;padding:20px;min-height:100vh}.container{max-width:900px;margin:0 auto}h1{text-align:center;color:#ff79c6;font-size:1.5em;margin-bottom:5px}h2{text-align:center;color:#6272a4;font-size:0.9em;margin-bottom:20px;font-weight:normal}.controls{display:flex;gap:20px;justify-content:center;flex-wrap:wrap;margin-bottom:20px;align-items:end}.control-group{display:flex;flex-direction:column;gap:4px}.control-group label{font-size:0.82em;color:#bd93f9}.control-group input{background:#1a1a2e;border:1px solid #44475a;color:#f8f8f2;padding:6px 10px;border-radius:6px;width:80px;font-size:0.9em}canvas{display:block;margin:0 auto;border-radius:10px;background:#0d1117;border:1px solid #44475a}table{width:100%;margin-top:15px;border-collapse:collapse}th,td{padding:8px 12px;text-align:center;border-bottom:1px solid #44475a;font-size:0.85em}th{color:#bd93f9;font-weight:600}td{color:#f8f8f2}.tighter{color:#50fa7b;font-weight:bold}.legend{display:flex;gap:20px;justify-content:center;margin-top:10px;font-size:0.85em}.legend-item{display:flex;align-items:center;gap:6px}.legend-dot{width:12px;height:12px;border-radius:50%}</style></head><body><div class=\"container\"><h1>📐 BabelCode Bounds Visualizer</h1><h2>Singleton vs. Hamming bounds on maximum code size</h2><div class=\"controls\"><div class=\"control-group\"><label>Alphabet Size (A)</label><input id=\"aInput\" type=\"number\" value=\"4\" min=\"2\" max=\"16\"></div><div class=\"control-group\"><label>Volume Length (L)</label><input id=\"lInput\" type=\"number\" value=\"12\" min=\"2\" max=\"30\"></div></div><canvas id=\"chart\" width=\"850\" height=\"400\"></canvas><div class=\"legend\"><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#ff79c6\"></div>Singleton Bound: A<sup>L−d+1</sup></div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#8be9fd\"></div>Hamming Bound: A<sup>L</sup>/|B(c,⌊(d−1)/2⌋)|</div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#50fa7b\"></div>Tighter bound</div></div><table id=\"dataTable\"><thead><tr><th>Min Dist (d)</th><th>Singleton</th><th>Hamming</th><th>Tighter</th><th>Error Correction</th></tr></thead><tbody id=\"tableBody\"></tbody></table></div><script>const chart=document.getElementById('chart'),cx=chart.getContext('2d');function C(n,k){if(k<0||k>n)return 0;if(k===0||k===n)return 1;let r=1;for(let i=0;i<k;i++)r=r*(n-i)/(i+1);return Math.round(r)}function ballSize(A,L,r){let s=0;for(let k=0;k<=r;k++)s+=C(L,k)*Math.pow(A-1,k);return s}function draw(){const A=parseInt(document.getElementById('aInput').value)||4;const L=parseInt(document.getElementById('lInput').value)||12;const libSize=Math.pow(A,L);const data=[];for(let d=1;d<=L;d++){const sing=Math.pow(A,L-d+1);const t=Math.floor((d-1)/2);const b=ballSize(A,L,t);const ham=Math.floor(libSize/b);data.push({d,sing,ham,t})}cx.clearRect(0,0,chart.width,chart.height);const pad={l:70,r:30,t:30,b:50};const w=chart.width-pad.l-pad.r;const h=chart.height-pad.t-pad.b;const maxVal=Math.max(...data.map(d=>Math.max(d.sing,d.ham)));const logMax=Math.log10(maxVal+1);cx.strokeStyle='#44475a';cx.lineWidth=1;cx.fillStyle='#6272a4';cx.font='11px sans-serif';cx.textAlign='right';cx.textBaseline='middle';const yTicks=6;for(let i=0;i<=yTicks;i++){const y=pad.t+h-i*(h/yTicks);const val=logMax*i/yTicks;cx.beginPath();cx.moveTo(pad.l,y);cx.lineTo(pad.l+w,y);cx.stroke();cx.fillText(val<1?'1':`10^${val.toFixed(1)}`,pad.l-8,y)}cx.textAlign='center';cx.textBaseline='top';data.forEach((d,i)=>{const x=pad.l+(i+0.5)*(w/data.length);cx.fillStyle='#6272a4';cx.fillText(d.d,x,pad.t+h+8)});cx.fillText('Minimum Distance (d)',pad.l+w/2,pad.t+h+30);cx.save();cx.translate(15,pad.t+h/2);cx.rotate(-Math.PI/2);cx.fillStyle='#6272a4';cx.textAlign='center';cx.fillText('Max Code Size (log scale)',0,0);cx.restore();function toY(val){const lv=val>0?Math.log10(val):0;return pad.t+h-h*(lv/logMax)}const barW=w/data.length*0.35;data.forEach((d,i)=>{const x=pad.l+(i+0.5)*(w/data.length);const ys=toY(d.sing);const yh=toY(d.ham);cx.fillStyle='#ff79c6';cx.globalAlpha=0.7;cx.fillRect(x-barW-1,ys,barW,pad.t+h-ys);cx.fillStyle='#8be9fd';cx.fillRect(x+1,yh,barW,pad.t+h-yh);cx.globalAlpha=1;const tighter=Math.min(d.sing,d.ham);const ty=toY(tighter);cx.fillStyle='#50fa7b';cx.beginPath();cx.arc(x,ty,3,0,Math.PI*2);cx.fill()});const tbody=document.getElementById('tableBody');tbody.innerHTML='';data.forEach(d=>{const tighter=d.ham<d.sing?'Hamming':d.sing<d.ham?'Singleton':'Equal';const tr=document.createElement('tr');tr.innerHTML=`<td>${d.d}</td><td>${fmtNum(d.sing)}</td><td>${fmtNum(d.ham)}</td><td class=\"tighter\">${tighter}</td><td>Corrects ${d.t} errors</td>`;tbody.appendChild(tr)})}function fmtNum(n){if(n>1e15)return'10^'+Math.log10(n).toFixed(1);return n.toLocaleString()}document.getElementById('aInput').addEventListener('input',draw);document.getElementById('lInput').addEventListener('input',draw);draw()</script></body></html>"
