      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>BabelCode Builder</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;justify-content:center;padding:20px}.main{max-width:900px;width:100%}h1{text-align:center;color:#ffd700;margin-bottom:4px}p.sub{text-align:center;color:#888;font-style:italic;margin-bottom:20px}.top{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:15px}.panel{background:#151530;border:1px solid #333;border-radius:8px;padding:15px}.panel h2{color:#88aaff;font-size:1em;margin-bottom:10px;border-bottom:1px solid #333;padding-bottom:4px}.row{display:flex;gap:3px;margin:4px 0;align-items:center}.sym{width:32px;height:32px;display:flex;align-items:center;justify-content:center;background:#0a0a20;border:1px solid #555;border-radius:4px;cursor:pointer;font-weight:bold;font-size:1em;user-select:none;transition:all .15s}.sym:hover{border-color:#88aaff}.sym.s0{color:#4caf50}.sym.s1{color:#ff9800}.sym.s2{color:#e040fb}.btn{padding:6px 14px;border-radius:5px;border:1px solid #555;cursor:pointer;font-size:.85em;margin:3px}.btn-add{background:#1a3a1a;color:#4caf50}.btn-add:hover{background:#2a5a2a}.btn-clear{background:#3a1a1a;color:#ff5252}.btn-clear:hover{background:#5a2a2a}.btn-rand{background:#1a1a3a;color:#88aaff}.btn-rand:hover{background:#2a2a5a}.metric{display:flex;justify-content:space-between;padding:5px 0;font-size:.9em}.metric .v{color:#4fc3f7;font-weight:bold;font-family:monospace}.cw-list{max-height:300px;overflow-y:auto}.cw-item{display:flex;align-items:center;gap:6px;padding:4px 6px;border-bottom:1px solid #1a1a3a;font-family:monospace;font-size:.85em}.cw-idx{color:#888;width:25px}.cw-del{cursor:pointer;color:#ff5252;font-size:.8em}.msg{padding:8px;border-radius:5px;margin-top:8px;font-size:.85em;text-align:center}.msg-ok{background:#1a3a1a;border:1px solid #2a5a2a;color:#4caf50}.msg-err{background:#3a1a1a;border:1px solid #5a2a2a;color:#ff5252}.msg-info{background:#1a1a3a;border:1px solid #2a2a5a;color:#88aaff}.gauge{margin-top:10px}.gauge-track{height:22px;background:#0a0a20;border-radius:5px;overflow:hidden;position:relative}.gauge-fill{height:100%;border-radius:5px;transition:width .3s}.gauge-text{position:absolute;left:50%;top:2px;transform:translateX(-50%);font-size:.8em;font-weight:bold;text-shadow:0 0 3px #000}</style></head><body><div class=\"main\"><h1>🔧 BabelCode Builder</h1><p class=\"sub\">Build an error-correcting code in a mini-Library (A=3, L=6). Set min distance d and add codewords.</p><div class=\"top\"><div class=\"panel\"><h2>New Codeword</h2><div class=\"row\" id=\"newCW\"></div><div style=\"margin-top:8px;display:flex;gap:5px;flex-wrap:wrap\"><button class=\"btn btn-add\" onclick=\"addCW()\">+ Add to Code</button><button class=\"btn btn-rand\" onclick=\"randCW()\">🎲 Random</button></div><div id=\"msg\"></div></div><div class=\"panel\"><h2>Parameters</h2><div class=\"metric\"><span>Alphabet A</span><span class=\"v\">3</span></div><div class=\"metric\"><span>Length L</span><span class=\"v\">6</span></div><div class=\"metric\"><span>Min Distance d</span><span class=\"v\"><input type=\"range\" id=\"dSlider\" min=\"1\" max=\"6\" value=\"3\" style=\"width:80px;vertical-align:middle\" oninput=\"updateD()\"> <span id=\"dVal\">3</span></span></div><div class=\"metric\"><span>Singleton Bound</span><span class=\"v\" id=\"singBound\">—</span></div><div class=\"metric\"><span>Code Size</span><span class=\"v\" id=\"codeSize\">0</span></div><div class=\"gauge\"><div style=\"font-size:.8em;color:#aaa;margin-bottom:3px\">Code Size / Singleton Bound</div><div class=\"gauge-track\"><div class=\"gauge-fill\" id=\"gaugeFill\" style=\"width:0%;background:linear-gradient(90deg,#4caf50,#ff9800,#ff5252)\"></div><div class=\"gauge-text\" id=\"gaugeText\">0%</div></div></div></div></div><div class=\"panel\"><h2>Codewords</h2><button class=\"btn btn-clear\" onclick=\"clearCode()\">🗑 Clear All</button><div class=\"cw-list\" id=\"cwList\"></div></div></div><script>const A=3,L=6;let d=3,code=[],newCW=[0,0,0,0,0,0];const colors=['s0','s1','s2'];function hamming(a,b){let c=0;for(let i=0;i<L;i++)if(a[i]!==b[i])c++;return c}function renderNew(){const el=document.getElementById('newCW');el.innerHTML='';for(let i=0;i<L;i++){const s=document.createElement('div');s.className='sym '+colors[newCW[i]];s.textContent=newCW[i];s.onclick=()=>{newCW[i]=(newCW[i]+1)%A;renderNew()};el.appendChild(s)}}function updateD(){d=+document.getElementById('dSlider').value;document.getElementById('dVal').textContent=d;renderCode()}function singleton(){return Math.pow(A,L-d+1)}function renderCode(){document.getElementById('singBound').textContent=singleton();document.getElementById('codeSize').textContent=code.length;const pct=code.length/singleton()*100;document.getElementById('gaugeFill').style.width=Math.min(100,pct)+'%';document.getElementById('gaugeText').textContent=Math.round(pct)+'%';const list=document.getElementById('cwList');list.innerHTML='';for(let j=0;j<code.length;j++){const item=document.createElement('div');item.className='cw-item';let minD=Infinity;for(let k=0;k<code.length;k++){if(k!==j){const dd=hamming(code[j],code[k]);if(dd<minD)minD=dd}}item.innerHTML=`<span class=\"cw-idx\">${j}</span><span>[${code[j].join(',')}]</span><span style=\"color:#888;margin-left:auto;font-size:.8em\">min_d=${minD===Infinity?'—':minD}</span><span class=\"cw-del\" onclick=\"delCW(${j})\"> ✕</span>`;list.appendChild(item)}}function addCW(){const cw=[...newCW];for(let j=0;j<code.length;j++){if(hamming(cw,code[j])===0){showMsg('Duplicate codeword!','err');return}if(hamming(cw,code[j])<d){showMsg(`Distance to codeword ${j} is ${hamming(cw,code[j])} < d=${d}. Rejected!`,'err');return}}if(code.length>=singleton()){showMsg(`Singleton bound reached! Cannot add more than ${singleton()} codewords.`,'err');return}code.push(cw);showMsg('Codeword added ✓','ok');renderCode()}function delCW(i){code.splice(i,1);renderCode()}function clearCode(){code=[];document.getElementById('msg').innerHTML='';renderCode()}function randCW(){newCW=Array.from({length:L},()=>Math.floor(Math.random()*A));renderNew()}function showMsg(t,type){document.getElementById('msg').innerHTML=`<div class=\"msg msg-${type}\">${t}</div>`;setTimeout(()=>{document.getElementById('msg').innerHTML=''},3000)}renderNew();renderCode()</script></body></html>"
