      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Hamming Geometry Explorer</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;padding:20px;min-height:100vh}.container{max-width:900px;margin:0 auto}h1{text-align:center;color:#8be9fd;margin-bottom:5px;font-size:1.6em}h2{text-align:center;color:#6272a4;font-size:0.95em;margin-bottom:20px;font-weight:normal}.controls{display:flex;gap:15px;justify-content:center;flex-wrap:wrap;margin-bottom:20px}.control-group{display:flex;flex-direction:column;align-items:center;gap:5px}.control-group label{font-size:0.85em;color:#bd93f9}.control-group select,.control-group input{background:#1a1a2e;border:1px solid #44475a;color:#f8f8f2;padding:6px 10px;border-radius:6px;font-size:0.9em}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:20px}.stat-card{background:linear-gradient(135deg,#1a1a2e,#16213e);border:1px solid #44475a;border-radius:10px;padding:12px;text-align:center}.stat-card .value{font-size:1.5em;color:#50fa7b;font-weight:bold}.stat-card .label{font-size:0.8em;color:#6272a4;margin-top:3px}canvas{display:block;margin:0 auto;border-radius:10px;background:#0d1117;border:1px solid #44475a}.volume-display{margin-top:15px;text-align:center;font-family:monospace;font-size:1.1em;color:#ff79c6}.info{margin-top:15px;background:#1a1a2e;border:1px solid #44475a;border-radius:8px;padding:12px;font-size:0.85em;line-height:1.6;color:#8be9fd}</style></head><body><div class=\"container\"><h1>📚 Hamming Geometry Explorer</h1><h2>Explore the geometry of a mini-Library of Babel</h2><div class=\"controls\"><div class=\"control-group\"><label>Alphabet (A)</label><select id=\"alphaSelect\"><option value=\"2\">2 (Binary)</option><option value=\"3\" selected>3 (Ternary)</option><option value=\"4\">4 (Quaternary)</option></select></div><div class=\"control-group\"><label>Length (L)</label><select id=\"lenSelect\"><option value=\"2\">2</option><option value=\"3\" selected>3</option><option value=\"4\">4</option></select></div><div class=\"control-group\"><label>Selected Volume</label><input id=\"volInput\" type=\"text\" value=\"000\" size=\"6\" placeholder=\"e.g. 012\"></div></div><div class=\"stats\"><div class=\"stat-card\"><div class=\"value\" id=\"libSize\">27</div><div class=\"label\">Library Size (A<sup>L</sup>)</div></div><div class=\"stat-card\"><div class=\"value\" id=\"degreeVal\">6</div><div class=\"label\">Neighbors L×(A−1)</div></div><div class=\"stat-card\"><div class=\"value\" id=\"diameterVal\">3</div><div class=\"label\">Diameter (L)</div></div><div class=\"stat-card\"><div class=\"value\" id=\"distVal\">—</div><div class=\"label\">Distance to Selected</div></div></div><canvas id=\"canvas\" width=\"800\" height=\"500\"></canvas><div class=\"volume-display\" id=\"volDisplay\"></div><div class=\"info\"><strong>Theorem (babel_degree):</strong> Every volume has exactly L×(A−1) = <span id=\"degreeFormula\"></span> Hamming neighbors.<br><strong>Theorem (babel_diameter_achieved):</strong> The maximum Hamming distance is L = <span id=\"diamFormula\"></span>, achieved by volumes differing in all positions.</div></div><script>const canvas=document.getElementById('canvas'),ctx=canvas.getContext('2d');let A=3,L=3,selectedVol='000',volumes=[],hoveredIdx=-1;function init(){A=parseInt(document.getElementById('alphaSelect').value);L=parseInt(document.getElementById('lenSelect').value);volumes=[];generateVolumes([],0);document.getElementById('libSize').textContent=Math.pow(A,L);document.getElementById('degreeVal').textContent=L*(A-1);document.getElementById('diameterVal').textContent=L;document.getElementById('degreeFormula').textContent=`${L}×${A-1} = ${L*(A-1)}`;document.getElementById('diamFormula').textContent=L;if(selectedVol.length!==L||[...selectedVol].some(c=>parseInt(c)>=A)){selectedVol='0'.repeat(L);document.getElementById('volInput').value=selectedVol}draw()}function generateVolumes(prefix,depth){if(depth===L){volumes.push(prefix.join(''));return}for(let i=0;i<A;i++)generateVolumes([...prefix,i],depth+1)}function hamming(a,b){let d=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])d++;return d}function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);if(volumes.length>256){ctx.fillStyle='#6272a4';ctx.font='16px sans-serif';ctx.textAlign='center';ctx.fillText(`Library has ${volumes.length} volumes — showing distance histogram`,400,250);drawHistogram();return}const n=volumes.length;const cols=Math.ceil(Math.sqrt(n*1.5));const rows=Math.ceil(n/cols);const cellW=canvas.width/cols;const cellH=canvas.height/rows;const maxDist=L;volumes.forEach((v,i)=>{const col=i%cols,row=Math.floor(i/cols);const x=col*cellW+cellW/2,y=row*cellH+cellH/2;const d=hamming(v,selectedVol);const isSelected=v===selectedVol;const isNeighbor=d===1;let color;if(isSelected)color='#ff79c6';else if(isNeighbor)color='#50fa7b';else{const t=d/maxDist;color=`hsl(${240-t*180},60%,${50-t*20}%)`}const r=Math.min(cellW,cellH)*0.35;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.globalAlpha=isSelected?1:isNeighbor?0.9:0.5;ctx.fill();ctx.globalAlpha=1;if(isSelected){ctx.strokeStyle='#ff79c6';ctx.lineWidth=2;ctx.stroke()}if(n<=64){ctx.fillStyle='#f8f8f2';ctx.font=`${Math.min(10,r*0.8)}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v,x,y)}});if(hoveredIdx>=0&&hoveredIdx<n){const d=hamming(volumes[hoveredIdx],selectedVol);document.getElementById('distVal').textContent=d;document.getElementById('volDisplay').textContent=`Hovered: ${volumes[hoveredIdx]} | Distance: ${d}`}else{document.getElementById('distVal').textContent='—';document.getElementById('volDisplay').textContent=`Selected: ${selectedVol} | Click a volume or type one above`}}function drawHistogram(){const counts=new Array(L+1).fill(0);volumes.forEach(v=>{const d=hamming(v,selectedVol);counts[d]++});const maxCount=Math.max(...counts);const barW=600/(L+1);const baseY=420,maxH=300;ctx.fillStyle='#6272a4';ctx.font='12px sans-serif';ctx.textAlign='center';for(let d=0;d<=L;d++){const h=maxCount>0?(counts[d]/maxCount)*maxH:0;const x=100+d*barW;const color=d===0?'#ff79c6':d===1?'#50fa7b':`hsl(${240-d/L*180},60%,40%)`;ctx.fillStyle=color;ctx.fillRect(x+5,baseY-h,barW-10,h);ctx.fillStyle='#f8f8f2';ctx.font='11px sans-serif';ctx.fillText(counts[d],x+barW/2,baseY-h-8);ctx.fillText(`d=${d}`,x+barW/2,baseY+15)}}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=(e.clientX-rect.left)*(canvas.width/rect.width);const my=(e.clientY-rect.top)*(canvas.height/rect.height);if(volumes.length>256)return;const n=volumes.length;const cols=Math.ceil(Math.sqrt(n*1.5));const cellW=canvas.width/cols;const cellH=canvas.height/Math.ceil(n/cols);hoveredIdx=-1;volumes.forEach((v,i)=>{const col=i%cols,row=Math.floor(i/cols);const x=col*cellW+cellW/2,y=row*cellH+cellH/2;const r=Math.min(cellW,cellH)*0.35;if(Math.hypot(mx-x,my-y)<r)hoveredIdx=i});draw()});canvas.addEventListener('click',()=>{if(hoveredIdx>=0&&hoveredIdx<volumes.length){selectedVol=volumes[hoveredIdx];document.getElementById('volInput').value=selectedVol;draw()}});document.getElementById('volInput').addEventListener('input',e=>{const v=e.target.value;if(v.length===L&&[...v].every(c=>{const d=parseInt(c);return!isNaN(d)&&d<A})){selectedVol=v;draw()}});document.getElementById('alphaSelect').addEventListener('change',init);document.getElementById('lenSelect').addEventListener('change',init);init()</script></body></html>"
