      "html": "<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><title>Singleton Bound Calculator</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;justify-content:center;padding:40px}main{max-width:800px;width:100%}h1{text-align:center;font-size:1.8em;margin-bottom:8px;background:linear-gradient(135deg,#f59e0b,#ef4444);-webkit-background-clip:text;-webkit-text-fill-color:transparent}p.sub{text-align:center;color:#888;margin-bottom:30px;font-size:.95em}.controls{background:#111827;border-radius:12px;padding:24px;margin-bottom:20px;border:1px solid #1e293b;display:grid;grid-template-columns:1fr 1fr;gap:16px}.ctrl{display:flex;flex-direction:column;gap:6px}.ctrl label{font-weight:600;color:#fbbf24;font-size:.9em}.ctrl input{background:#1e293b;border:1px solid #334155;border-radius:8px;padding:8px 12px;color:#e0e0e0;font-size:1em}.ctrl .val{color:#fbbf24;font-size:.85em;text-align:right}canvas{width:100%;height:300px;background:#111827;border-radius:12px;border:1px solid #1e293b;margin-bottom:20px}table{width:100%;border-collapse:collapse;background:#111827;border-radius:12px;overflow:hidden;border:1px solid #1e293b}th{background:#1e293b;color:#fbbf24;padding:12px;text-align:left;font-size:.9em}td{padding:10px 12px;border-top:1px solid #1e293b;font-size:.9em;font-family:'Courier New',monospace}tr:hover{background:#1e293b55}.bar{height:16px;border-radius:4px;background:linear-gradient(90deg,#f59e0b,#ef4444);transition:width .3s}</style></head><body><main><h1>\ud83d\udcca Singleton Bound Calculator</h1><p class='sub'>|C| \u2264 A^(L \u2212 d + 1) for BabelCode with min distance d</p><div class='controls'><div class='ctrl'><label>Alphabet Size (A)</label><input type='range' id='aSlider' min='2' max='30' value='4'><div class='val'>A = <span id='aVal'>4</span></div></div><div class='ctrl'><label>Book Length (L)</label><input type='range' id='lSlider' min='2' max='64' value='16'><div class='val'>L = <span id='lVal'>16</span></div></div></div><canvas id='chart'></canvas><table><thead><tr><th>Min Dist (d)</th><th>Bound A^(L-d+1)</th><th>Fraction of Library</th><th>Visual</th></tr></thead><tbody id='tbody'></tbody></table></main><script>const aS=document.getElementById('aSlider'),lS=document.getElementById('lSlider'),aV=document.getElementById('aVal'),lV=document.getElementById('lVal'),tbody=document.getElementById('tbody'),canvas=document.getElementById('chart'),ctx=canvas.getContext('2d');function fmt(n){if(n<1e15)return n.toLocaleString();const e=Math.log10(n);return'\\u224810^'+e.toFixed(1)}function update(){const A=parseInt(aS.value),L=parseInt(lS.value);aV.textContent=A;lV.textContent=L;const total=Math.pow(A,L);let rows='';const dpi=window.devicePixelRatio||1;canvas.width=canvas.clientWidth*dpi;canvas.height=canvas.clientHeight*dpi;ctx.scale(dpi,dpi);const W=canvas.clientWidth,H=canvas.clientHeight;ctx.clearRect(0,0,W,H);ctx.fillStyle='#111827';ctx.fillRect(0,0,W,H);const pad={t:30,r:20,b:40,l:60},pw=W-pad.l-pad.r,ph=H-pad.t-pad.b;ctx.strokeStyle='#334155';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad.l,pad.t);ctx.lineTo(pad.l,pad.t+ph);ctx.lineTo(pad.l+pw,pad.t+ph);ctx.stroke();ctx.fillStyle='#888';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText('Minimum Distance (d)',pad.l+pw/2,H-5);ctx.save();ctx.translate(15,pad.t+ph/2);ctx.rotate(-Math.PI/2);ctx.fillText('log\\u2081\\u2080(Bound)',0,0);ctx.restore();const maxLog=L*Math.log10(A);const points=[];for(let d=1;d<=L;d++){const exp=L-d+1;const logBound=exp*Math.log10(A);const x=pad.l+((d-1)/(L-1))*pw;const y=pad.t+ph-(logBound/maxLog)*ph;points.push({d,x,y,logBound,exp});const frac=Math.pow(A,-(d-1));if(d<=L&&(d<=10||d%Math.ceil(L/10)===0||d===L)){const bound=exp>=0?BigInt(A)**BigInt(exp):0n;rows+=`<tr><td>${d}</td><td>${exp>=0?'A^'+exp+' = '+fmt(Number(bound)):'0'}</td><td>${frac<1e-10?frac.toExponential(2):(frac*100).toFixed(4)+'%'}</td><td><div class='bar' style='width:${Math.max(1,frac*100)}%'></div></td></tr>`}}ctx.strokeStyle='#f59e0b';ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>{i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y)});ctx.stroke();ctx.fillStyle='#f59e0b';points.forEach(p=>{if(p.d===1||p.d===L||p.d===Math.ceil(L/2)){ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);ctx.fill()}});for(let i=0;i<=4;i++){const logVal=(i/4)*maxLog;const y=pad.t+ph-(logVal/maxLog)*ph;ctx.fillStyle='#888';ctx.font='10px system-ui';ctx.textAlign='right';ctx.fillText(logVal.toFixed(1),pad.l-8,y+3);ctx.strokeStyle='#1e293b';ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke()}tbody.innerHTML=rows}aS.addEventListener('input',update);lS.addEventListener('input',update);update()</script></body></html>"
