      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.4em;margin-bottom:4px;color:#8af}h2{font-size:.9em;font-weight:400;color:#888;margin-bottom:16px}canvas{border-radius:12px;background:#12122a;cursor:pointer}.info{margin-top:12px;padding:12px 20px;background:#1a1a2e;border-radius:8px;max-width:600px;text-align:center;font-size:.85em;line-height:1.5}.legend{display:flex;gap:16px;margin-top:8px;font-size:.8em}.legend span{display:flex;align-items:center;gap:4px}.dot{width:12px;height:12px;border-radius:50%;display:inline-block}</style></head><body><h1>The Counterpoint Quiver Q(CS₁₂)</h1><h2>6 consonant intervals · 410 permitted voice leadings</h2><canvas id=\"c\" width=\"600\" height=\"600\"></canvas><div class=\"legend\"><span><span class=\"dot\" style=\"background:#ff6b6b\"></span> Perfect consonance</span><span><span class=\"dot\" style=\"background:#4ecdc4\"></span> Imperfect consonance</span></div><div class=\"info\" id=\"info\">Click a node to see its connections. Edges show permitted voice leadings between intervals.</div><script>const W=600,H=600,cx=W/2,cy=H/2,R=200;const intervals=[{id:0,name:'Unison (0)',perfect:true},{id:3,name:'min 3rd (3)',perfect:false},{id:4,name:'Maj 3rd (4)',perfect:false},{id:7,name:'P5 (7)',perfect:true},{id:8,name:'min 6th (8)',perfect:false},{id:9,name:'Maj 6th (9)',perfect:false}];const N=12;function homCount(src,tgt){if(src===tgt)return intervals.find(x=>x.id===src).perfect?1:12;return 12;}const positions=intervals.map((_,i)=>{const a=-Math.PI/2+i*2*Math.PI/6;return{x:cx+R*Math.cos(a),y:cy+R*Math.sin(a)};});let selected=-1;const canvas=document.getElementById('c'),ctx=ca