= '+cost(m1.map((v,i)=>v+m2[i]))+' ≤ '+c1v+' + '+c2v+' = '+(c1v+c2v)+(triOk?' ✓':' ✗');tri.className='equation '+(triOk?'eq-true':'eq-false');makeBars('bars1',m1,'#ff6b9d');makeBars('bars2',m2,'#60a5fa');makeBars('bars-meet',mt,'#6f6');makeBars('bars-join',jn,'#fd0')}m1=[3,-2,5,-1];m2=[1,4,-3,2];makeSliders('s1',m1,'#ff6b9d');makeSliders('s2',m2,'#60a5fa');update()</script></body></html>"
