ost = '+cm;document.getElementById('cj').textContent='cost = '+cj;document.getElementById('meet_vals').textContent='['+mt.join(', ')+']';document.getElementById('join_vals').textContent='['+jn.join(', ')+']';document.getElementById('lhs1').textContent=cm;document.getElementById('lhs2').textContent=cj;document.getElementById('rhs1').textContent=c1;document.getElementById('rhs2').textContent=c2;const lhs=cm+cj,rhs=c1+c2;document.getElementById('result').innerHTML=lhs===rhs?`<span class=\"ok\">✓ Identity holds: ${lhs} = ${rhs}</span><br><span style=\"font-size:.8em;color:#888\">Displacement is conserved under lattice decomposition</span>`:`<span style=\"color:#ff6b6b\">✗ ${lhs} ≠ ${rhs}</span>`}makeInputs('m1',defaults1,'a');makeInputs('m2',defaults2,'b');update()</script></body></html>"
