an><span class=\"value\">4 (3,4,8,9)</span></div><div class=\"legend\"><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#ff6b6b\"></div>Perfect consonance</div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:#51cf66\"></div>Imperfect consonance</div><div class=\"legend-item\"><div class=\"legend-dot\" style=\"background:rgba(120,180,255,0.15)\"></div>Edge (voice leading)</div></div><div class=\"selected-info\" id=\"selInfo\">Click a node to see details.</div></div></div><script>const CONSONANT=[0,3,4,7,8,9],PERFECT=new Set([0,7]),N=12;const NAMES={0:'Unison',3:'Min 3rd',4:'Maj 3rd',7:'Perf 5th',8:'Min 6th',9:'Maj 6th'};function countPermitted(s,t){let c=0;for(let b=0;b<N;b++){let sp=(t-s+b+N*3)%N;let par=b===sp&&b!==0;if(!(PERFECT.has(t)&&par))c++}return c}const edges=[];let totalE=0;for(const s of CONSONANT)for(const t of CONSONANT){const n=countPermitted(s,t);edges.push({s,t,n});totalE+=n}document.getElementById('totalEdges').textContent=totalE;const cv=document.getElementById('c'),ctx=cv.getContext('2d');const W=cv.width,H=cv.height,CX=W/2,CY=H/2,R=180;const pos={};CONSONANT.forEach((v,i)=>{const a=-Math.PI/2+i*2*Math.PI/6;pos[v]={x:CX+R*Math.cos(a),y:CY+R*Math.sin(a)}});let selected=null;function selfLoops(v){return PERFECT.has(v)?1:12}function draw(){ctx.clearRect(0,0,W,H);for(const e of edges){if(e.n===0)continue;const p1=pos[e.s],p2=pos[e.t];if(e.s===e.t)continue;const hi=selected!==null&&(e.s===selected||e.t===selected);const alpha=hi?0.7:0.08;const width=hi?Math.max(1,e.n/4):0.5;ctx.beginPath();const mx=(p1.x+p2.x)/2,my=(p1.y+p2.y)/2;const dx=p2.x-p1.x,dy=p2.y-p1.y;const nx=-dy*0.12,ny=dx*0.12;ctx.moveTo(p1.x,p1.y);ctx.quadraticCurveTo(mx+nx,my+ny,p2.x,p2.y);ctx.strokeStyle=hi?(e.t===selected?'rgba(255,200,50,'+alpha+')':'rgba(100,200,255,'+alpha+')'):'rgba(120,180,255,'+alpha+')';ctx.lineWidth=width;ctx.stroke();if(hi){const t2=0.85;const ax=p1.x+(p2.x-p1.x)*t2+(mx+nx-p1.x)*2*t2*(1-t2)*0.1;const ay=p1.y+(p2.y-p1.y)*t2+(my+ny-p1.y)*2*t2*(1-t2)*0.1;ctx.beginPath();ctx.arc(ax,ay,3,0,Math.PI*2);ctx.fillStyle=ctx.strokeStyle;ctx.fill()}}for(const v of CONSONANT){const p=pos[v];const isPerfect=PERFECT.has(v);const isSel=v===selected;const r=isSel?28:22;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=isSel?(isPerfect?'#ff8787':'#69db7c'):(isPerfect?'#c92a2a':'#2b8a3e');ctx.fill();ctx.strokeStyle=isSel?'#fff':'rgba(255,255,255,0.3)';ctx.lineWidth=isSel?2.5:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=(isSel?'bold ':'')+' 11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(NAMES[v],p.x,p.y-1);ctx.font='9px system-ui';ctx.fillStyle='rgba(255,255,255,0.6)';ctx.fillText('('+v+')',p.x,p.y+12)}}cv.addEventListener('click',e=>{const rect=cv.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let hit=null;for(const v of CONSONANT){const p=pos[v];if(Math.hypot(mx-p.x,my-p.y)<28){hit=v;break}}selected=hit===selected?null:hit;draw();const info=document.getElementById('selInfo');if(selected===null){info.innerHTML='Click a node to see details.';return}const v=selected;const inE=edges.filter(e=>e.t===v).reduce((a,e)=>a+e.n,0);const outE=edges.filter(e=>e.s===v).reduce((a,e)=>a+e.n,0);const sl=selfLoops(v);info.innerHTML=`<strong>${NAMES[v]} (${v})</strong><br>Type: ${PERFECT.has(v)?'Perfect':'Imperfect'}<br>Self-loops: ${sl}<br>Total incoming: ${inE}<br>Total outgoing: ${outE}<br><br><em>Incoming from:</em><br>`+CONSONANT.map(s=>`${NAMES[s]}: ${countPermitted(s,v)} VLs`).join('<br>')});draw()</script></body></html>"
    },
    {
      "title": "Self-Loop Bottleneck: Perfect vs Imperfect",
      "description": "Interactive comparison of self-loops at perfect and imperfect consonances, illustrating the 12:1 asymmetry that is the mathematical heart of the parallel-fifths rule.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Self-Loop Bottleneck</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:24px;min-height:100vh}h1{color:#7eb8ff;font-size:1.3em;margin-bottom:4px}h2{color:#888;font-size:.9em;font-weight:400;margin-bottom:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;max-width:800px;width:100%}.card{background:#16163a;border-radius:12px;padding:20px;text-align:center;transition:transform .2s}.card:hover{transform:translateY(-2px)}.card h3{font-size:1em;margin-bottom:4px}.card .type{font-size:.8em;color:#888;margin-bottom:12px}.bar-container{display:flex;align-items:flex-end;justify-content:center;height:120px;gap:3px;margin-bottom:8px}.bar{width:14px;border-radius:3px 3px 0 0;transition:height .5s ease}.count{font-size:2em;font-weight:700;margin-bottom:4px}.ratio-section{margin-top:24px;background:#16163a;border-radius:12px;padding:20px 30px;max-width:800px;width:100%;text-align:center}.ratio-section h3{color:#7eb8ff;margin-bottom:10px}.ratio-bar{display:flex;height:40px;border-radius:8px;overflow:hidden;margin:12px 0}.ratio-bar .seg{display:flex;align-items:center;justify-content:center;font-weight:600;font-size:.85em;color:#fff}.explanation{font-size:.9em;color:#aaa;line-height:1.6;margin-top:12px;text-align:left;max-width:700px}</style></head><body><h1>Self-Loop Bottleneck Theorem</h1><h2>Perfect consonances: 1 self-loop · Imperfect consonances: 12 self-loops</h2><div class=\"grid\" id=\"grid\"></div><div class=\"ratio-section\"><h3>The 12:1 Asymmetry</h3><div class=\"ratio-bar\"><div class=\"seg\" style=\"flex:1;background:#c92a2a\">1 (Perfect)</div><div class=\"seg\" style=\"flex:12;background:#2b8a3e\">12 (Imperfect)</div></div><p class=\"explanation\">A <strong>self-loop</strong> is a voice leading where both voices move but the interval stays the same. For a <strong>perfect consonance</strong> (unison or fifth), only the identity — both voices holding still — is allowed. Any parallel motion (both voices moving identically) into a perfect consonance is <em>forbidden</em>. For an <strong>imperfect consonance</strong> (thirds and sixths), all 12 parallel motions are permitted. This 12:1 ratio is the quantitative signature of the parallel-fifths rule.</p></div><script>const data=[{name:'Unison',interval:0,perfect:true,loops:1},{name:'Minor 3rd',interval:3,perfect:false,loops:12},{name:'Major 3rd',interval:4,perfect:false,loops:12},{name:'Perfect 5th',interval:7,perfect:true,loops:1},{name:'Minor 6th',interval:8,perfect:false,loops:12},{name:'Major 6th',interval:9,perfect:false,loops:12}];const grid=document.getElementById('grid');data.forEach(d=>{const card=document.createElement('div');card.className='card';const bars=Array.from({length:12},(_,i)=>{const active=i<d.loops;const h=active?80:8;const color=active?(d.perfect?'#ff6b6b':'#51cf66'):'#222';return`<div class=\"bar\" style=\"height:${h}px;background:${color}\"></div>`}).join('');card.innerHTML=`<h3>${d.name} (${d.interval})</h3><div class=\"type\">${d.perfect?'PERFECT':'IMPERFECT'} consonance</div><div class=\"bar-container\">${bars}</div><div class=\"count\" style=\"color:${d.perfect?'#ff6b6b':'#51cf66'}\">${d.loops}</div><div style=\"font-size:.8em;color:#888\">self-loop${d.loops!==1?'s':''}</div>`;grid.appendChild(card)})</script></body></html>"
    },
    {
      "title": "Voice-Swap Symmetry Breaking on the Chromatic Circle",
      "description": "Visualize how the involution i ↦ -i (mod 12) acts on the chromatic circle and breaks consonance — the perfect fifth maps to the dissonant perfect fourth.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Voice-Swap Symmetry</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:24px;min-height:100vh}h1{color:#7eb8ff;font-size:1.3em;margin-bottom:4px}h2{color:#888;font-size:.9em;font-weight:400;margin-bottom:20px}.main{display:flex;gap:30px;flex-wrap:wrap;justify-content:center;align-items:flex-start}canvas{border-radius:12px;background:#12122a;cursor:pointer}.panel{background:#16163a;border-radius:12px;padding:20px;max-width:300px;min-width:240px}.panel h3{color:#7eb8ff;margin-bottom:10px;font-size:1em}.mapping{padding:6px 0;border-bottom:1px solid #222;font-size:.9em;display:flex;justify-content:space-between;align-items:center}.arrow{color:#666;margin:0 6px}.result{font-weight:600}.key-insight{margin-top:16px;background:#1a1a3a;border-left:3px solid #ff6b6b;padding:12px;border-radius:0 8px 8px 0;font-size:.85em;line-height:1.6}</style></head><body><h1>Voice-Swap Symmetry Breaking</h1><h2>The map i ↦ −i (mod 12) does not preserve consonance</h2><div class=\"main\"><canvas id=\"c\" width=\"440\" height=\"440\"></canvas><div class=\"panel\"><h3>Negation Map on Consonances</h3><div id=\"mappings\"></div><div class=\"key-insight\"><strong>Key insight:</strong> The perfect fifth (7) maps to 5 — the perfect fourth, which is <em>dissonant</em> in counterpoint. This breaks the symmetry of voice exchange and formalizes why the bass voice has a privileged role.</div></div></div><script>const N=12,R=170,CX=220,CY=220;const NAMES=['P1','m2','M2','m3','M3','P4','TT','P5','m6','M6','m7','M7'];const CONSONANT=new Set([0,3,4,7,8,9]);const cv=document.getElementById('c'),ctx=cv.getContext('2d');let hovered=null;function pos(i){const a=-Math.PI/2+i*2*Math.PI/N;return{x:CX+R*Math.cos(a),y:CY+R*Math.sin(a)}}function draw(){ctx.clearRect(0,0,440,440);ctx.beginPath();ctx.arc(CX,CY,R,0,Math.PI*2);ctx.strokeStyle='rgba(255,255,255,0.08)';ctx.lineWidth=1;ctx.stroke();if(hovered!==null){const neg=(N-hovered)%N;const p1=pos(hovered),p2=pos(neg);ctx.beginPath();ctx.setLineDash([6,4]);ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.strokeStyle='rgba(255,200,50,0.5)';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([])}for(let i=0;i<N;i++){const p=pos(i);const isCon=CONSONANT.has(i);const isHov=i===hovered;const neg=(N-hovered)%N;const isNeg=hovered!==null&&i===neg;const r=isHov||isNeg?20:isCon?16:12;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);if(isHov)ctx.fillStyle='#ffd43b';else if(isNeg)ctx.fillStyle=CONSONANT.has(i)?'#51cf66':'#ff6b6b';else ctx.fillStyle=isCon?'rgba(100,200,100,0.7)':'rgba(80,80,100,0.5)';ctx.fill();ctx.strokeStyle=isHov||isNeg?'#fff':'rgba(255,255,255,0.2)';ctx.lineWidth=isHov||isNeg?2:1;ctx.stroke();ctx.fillStyle=isHov||isNeg?'#000':'#ddd';ctx.font=(isHov||isNeg?'bold ':'')+'11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(NAMES[i],p.x,p.y);if(isCon||isHov||isNeg){ctx.fillStyle='rgba(255,255,255,0.5)';ctx.font='9px system-ui';ctx.fillText(i.toString(),p.x,p.y+r+10)}}}cv.addEventListener('mousemove',e=>{const rect=cv.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let hit=null;for(let i=0;i<N;i++){const p=pos(i);if(Math.hypot(mx-p.x,my-p.y)<22){hit=i;break}}if(hit!==hovered){hovered=hit;draw()}});cv.addEventListener('mouseleave',()=>{hovered=null;draw()});const mp=document.getElementById('mappings');[0,3,4,7,8,9].forEach(i=>{const neg=(N-i)%N;const ok=CONSONANT.has(neg);const d=document.createElement('div');d.className='mapping';d.innerHTML=`<span>${NAMES[i]} (${i})</span><span class=\"arrow\">↦</span><span class=\"result\" style=\"color:${ok?'#51cf66':'#ff6b6b'}\">${NAMES[neg]} (${neg}) ${ok?'✓':'✗'}</span>`;mp.appendChild(d)});draw()</script></body></html>"
