the bass voice.</span>';panel.innerHTML=html;pairs.forEach((p,idx)=>{setTimeout(()=>{notes[p.from].classList.add('highlight');const a1=-Math.PI/2+p.from*Math.PI*2/12;const a2=-Math.PI/2+p.to*Math.PI*2/12;const x1=cx+R*Math.cos(a1);const y1=cy+R*Math.sin(a1);const x2=cx+R*Math.cos(a2);const y2=cy+R*Math.sin(a2);if(p.from!==p.to){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','arrow-svg');svg.style.cssText='position:absolute;left:0;top:0;width:500px;height:500px;pointer-events:none;z-index:3';const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);line.setAttribute('stroke',p.ok?'#44ff88':'#ff4444');line.setAttribute('stroke-width','2');line.setAttribute('stroke-dasharray','6,4');svg.appendChild(line);clock.appendChild(svg)}if(!p.ok){notes[p.to].style.border='3px solid #ff4444';notes[p.to].style.boxShadow='0 0 15px rgba(255,68,68,.5)'}},idx*400)})}showAll()</script></body></html>"
